part of '../../main.dart';

const List<Study> studyCatalog10 = <Study>[
Study(
    number: '73',
    title: "La mayordomía cristiana: responsabilidad delante de Dios en el uso del tiempo, las capacidades, los recursos y la creación",
    subtitle: "Un estudio bíblico sobre la fidelidad del creyente en la administración del tiempo, las capacidades, los bienes, las relaciones y la creación que Dios ha confiado.",
    introduction: "La mayordomía cristiana parte de una verdad fundamental: Dios es el Creador y dueño de todo, mientras que el ser humano recibe de él la vida y diversas responsabilidades. Por eso, administrar no consiste únicamente en manejar dinero, sino en vivir con fidelidad delante de Dios en el uso del tiempo, las capacidades, el cuerpo, el trabajo, los recursos materiales, las oportunidades, las relaciones y la creación. La Escritura enseña que los administradores deben ser hallados fieles y que cada persona dará cuenta de su vida delante del Señor. Este estudio examina los principios bíblicos de propiedad divina, responsabilidad, planificación, honestidad, generosidad, justicia, moderación y rendición de cuentas. También distingue la mayordomía de la búsqueda de prosperidad como señal de aprobación divina, y recuerda que las buenas obras no compran la salvación: son fruto de la gracia recibida. Desde la perspectiva trinitaria, el Padre es Creador, el Hijo es Señor y modelo de entrega, y el Espíritu Santo capacita para servir; así, toda la vida del creyente debe administrarse para la gloria de Dios.",
    sections: [
      StudySection(title: "1. Dios es dueño de todo", content: "Dios es Creador y dueño de cuanto existe. El ser humano no es propietario absoluto, sino criatura que recibe bienes y responsabilidades bajo el Señor.", references: "Sal 24:1; 1 Cr 29:11-14"),
      StudySection(title: "2. El ser humano como administrador", content: "Desde la creación, Dios confió al ser humano responsabilidades sobre la tierra. Esto implica cuidado y servicio, no explotación egoísta.", references: "Gn 1:26-28; 2:15"),
      StudySection(title: "3. La mayordomía nace de la creación", content: "La responsabilidad no comienza con la posesión de riquezas. Toda vida, capacidad y oportunidad procede de Dios y debe orientarse a sus propósitos.", references: "Gn 2:7; Hch 17:24-25"),
      StudySection(title: "4. Fidelidad en lo encomendado", content: "La fidelidad se demuestra al cuidar lo confiado, aunque parezca pequeño o poco visible. Dios llama a administrar con integridad y constancia.", references: "Lc 16:10-12; 1 Co 4:2"),
      StudySection(title: "5. Responsabilidad ante el Señor", content: "El administrador debe recordar que rendirá cuentas a Dios. Esta verdad invita a actuar con reverencia y responsabilidad moral.", references: "Ro 14:12; 2 Co 5:10"),
      StudySection(title: "6. Gracia y bienes recibidos", content: "Las capacidades y oportunidades no son motivo de orgullo, porque dependen de la bondad de Dios. La gratitud conduce al servicio responsable.", references: "1 Co 4:7; Stg 1:17"),
      StudySection(title: "7. El tiempo como encargo", content: "La vida tiene duración limitada. Administrar el tiempo significa ordenar prioridades conforme a la voluntad de Dios.", references: "Sal 90:12; Ef 5:15-16"),
      StudySection(title: "8. Prioridades del reino", content: "Jesús enseñó a buscar primero el reino de Dios y su justicia. Las prioridades cristianas no deben quedar gobernadas por la ansiedad material.", references: "Mt 6:25-34"),
      StudySection(title: "9. Diligencia y trabajo", content: "La diligencia permite cumplir responsabilidades y contribuir al bienestar propio y ajeno. El trabajo debe realizarse sin pereza ni engaño.", references: "Pr 6:6-11; Col 3:23-24"),
      StudySection(title: "10. El trabajo como servicio", content: "El creyente puede realizar sus labores como servicio al Señor. La calidad del trabajo nace de una conciencia delante de Dios.", references: "Col 3:17,23; Ef 6:7"),
      StudySection(title: "11. Honestidad económica", content: "La administración exige verdad en los acuerdos, medidas justas y rechazo del fraude. La ganancia por engaño contradice la justicia divina.", references: "Pr 11:1; Lv 19:35-36; Ef 4:28"),
      StudySection(title: "12. Planificación prudente", content: "La prudencia considera recursos disponibles y responsabilidades, y evita compromisos temerarios. Planificar es actuar con sensatez.", references: "Pr 21:5; Lc 14:28-30"),
      StudySection(title: "13. Dependencia al planificar", content: "Santiago advierte contra presumir del mañana. La planificación cristiana reconoce que la vida y los resultados están en manos de Dios.", references: "Stg 4:13-16; Pr 16:3"),
      StudySection(title: "14. Uso de recursos materiales", content: "Los bienes deben utilizarse con gratitud, moderación y propósito. No deben convertirse en medida del valor personal.", references: "1 Ti 6:17-19; Mt 6:19-21"),
      StudySection(title: "15. Posesión y avaricia", content: "La Biblia no identifica toda posesión con pecado, pero advierte contra el deseo desordenado de acumular. La avaricia compite con Dios.", references: "Lc 12:15; Col 3:5"),
      StudySection(title: "16. No servir a las riquezas", content: "Jesús enseñó que nadie puede servir a dos señores. El dinero puede ser herramienta, pero nunca debe recibir la devoción debida a Dios.", references: "Mt 6:24; 1 Ti 6:9-10"),
      StudySection(title: "17. Contentamiento", content: "El contentamiento permite vivir con gratitud sin hacer de la abundancia una condición para la paz. Pablo aprendió a depender de Dios en toda situación.", references: "Fil 4:11-13; Heb 13:5"),
      StudySection(title: "18. Generosidad agradecida", content: "La generosidad responde a la gracia recibida y procura el bien del prójimo. Debe ser voluntaria y sincera, no un intento de comprar el favor divino.", references: "2 Co 9:6-8; Hch 20:35"),
      StudySection(title: "19. Ayuda al necesitado", content: "La administración fiel considera las necesidades reales de otros. La fe se expresa mediante ayuda concreta, compasión y solidaridad.", references: "1 Jn 3:17-18; Stg 2:15-17"),
      StudySection(title: "20. Justicia con el trabajador", content: "La Biblia condena retener injustamente el salario y aprovecharse de quien trabaja. La mayordomía exige tratar a colaboradores con justicia.", references: "Dt 24:14-15; Stg 5:4; Col 4:1"),
      StudySection(title: "21. Cuidado de la familia", content: "Las responsabilidades familiares forman parte de la vida confiada por Dios. Proveer y cuidar debe hacerse con amor y equilibrio.", references: "1 Ti 5:8; Ef 6:4"),
      StudySection(title: "22. Capacidades como encargos", content: "Las habilidades intelectuales, prácticas y creativas deben desarrollarse y ponerse al servicio del bien, no para manipular o perjudicar.", references: "Ex 31:1-6; 1 P 4:10"),
      StudySection(title: "23. Formación y aprendizaje", content: "Desarrollar conocimientos puede ser una forma de administrar oportunidades recibidas. El conocimiento debe acompañarse de humildad y servicio.", references: "Pr 1:5; 18:15"),
      StudySection(title: "24. Responsabilidad sobre el cuerpo", content: "El cuerpo no debe tratarse con desprecio ni considerarse propiedad sin propósito. La vida corporal debe honrar a Dios con decisiones prudentes.", references: "1 Co 6:19-20; Ro 12:1"),
      StudySection(title: "25. Mayordomía de las palabras", content: "Las palabras pueden edificar o dañar. Administrar el habla exige verdad, prudencia y consideración por quienes escuchan.", references: "Ef 4:29; Col 4:6"),
      StudySection(title: "26. Influencia y ejemplo", content: "Toda persona ejerce influencia en su entorno. Debe utilizarla para animar al bien, modelar integridad y evitar el abuso de autoridad.", references: "Mt 5:13-16; 1 Ti 4:12"),
      StudySection(title: "27. Oportunidades para servir", content: "Las oportunidades no deben desperdiciarse por indiferencia ni buscarse por reconocimiento. El creyente debe hacer el bien cuando tenga ocasión.", references: "Gá 6:9-10; Tit 3:14"),
      StudySection(title: "28. Responsabilidades en la Iglesia", content: "Quienes reciben tareas en la congregación deben cumplirlas con fidelidad, transparencia y espíritu de servicio. La obra pertenece al Señor.", references: "1 Co 4:1-2; 1 P 5:2-3"),
      StudySection(title: "29. Transparencia en los fondos", content: "La administración de recursos comunitarios requiere procedimientos honestos y rendición de cuentas. La confianza se protege evitando prácticas ocultas.", references: "2 Co 8:20-21; Ro 12:17"),
      StudySection(title: "30. Ofrenda voluntaria", content: "La contribución cristiana debe surgir de una decisión libre y alegre. La Escritura rechaza la presión manipuladora.", references: "2 Co 9:7; 1 Co 16:1-2"),
      StudySection(title: "31. Las obras no compran salvación", content: "La generosidad no compra el perdón ni hace merecedor de salvación. Las buenas obras son respuesta de gratitud y fruto de la gracia.", references: "Ef 2:8-10; Tit 3:5-8"),
      StudySection(title: "32. Mayordomía de la creación", content: "La humanidad recibió responsabilidad de cuidar la tierra. Su uso debe reconocer que la creación pertenece a Dios.", references: "Gn 2:15; Sal 24:1"),
      StudySection(title: "33. Cuidado de los animales", content: "La responsabilidad sobre la creación incluye trato considerado hacia los animales. La compasión y el cuidado expresan justicia.", references: "Pr 12:10; Gn 1:26"),
      StudySection(title: "34. Consumo moderado", content: "El consumo debe distinguir entre necesidad, comodidad y deseo desordenado. La moderación evita desperdicio y considera al prójimo.", references: "Pr 25:16; 1 Co 10:31"),
      StudySection(title: "35. Evitar el desperdicio", content: "La abundancia no justifica desperdiciar. Jesús mandó recoger lo sobrante después de alimentar a la multitud, mostrando cuidado de los recursos.", references: "Jn 6:12-13; Pr 18:9"),
      StudySection(title: "36. Deuda y prudencia", content: "La Escritura advierte del peligro de quedar sometido por obligaciones financieras. Endeudarse exige prudencia, honestidad y capacidad de cumplir.", references: "Pr 22:7; Ro 13:7-8"),
      StudySection(title: "37. Generosidad sin ostentación", content: "Jesús enseñó que la ayuda no debe realizarse para recibir aplausos. La motivación correcta busca agradar al Padre y atender al necesitado.", references: "Mt 6:1-4"),
      StudySection(title: "38. Abundancia y previsión", content: "La abundancia exige responsabilidad y previsión. La prosperidad no debe producir orgullo, sino administración prudente y atención a otros.", references: "Gn 41:33-36; 1 Ti 6:17-19"),
      StudySection(title: "39. Fidelidad en escasez", content: "La escasez requiere decisiones cuidadosas y confianza en Dios. La comunidad debe acompañar a quienes atraviesan necesidad.", references: "Fil 4:12-13; 2 Co 8:1-4"),
      StudySection(title: "40. Evitar comparación material", content: "Comparar la vida con la riqueza ajena puede alimentar envidia y descontento. La identidad del creyente no se define por su nivel económico.", references: "Sal 73:1-3,16-17; Gá 6:4"),
      StudySection(title: "41. Riqueza y responsabilidad social", content: "Quienes poseen recursos deben hacer el bien y compartir. La riqueza debe administrarse con humildad y esperanza puesta en Dios.", references: "1 Ti 6:17-19; Stg 1:10-11"),
      StudySection(title: "42. Rendición de cuentas", content: "Las parábolas de Jesús recuerdan que el administrador responde por lo recibido. Esto impulsa fidelidad y responsabilidad.", references: "Mt 25:14-30; Lc 12:42-48"),
      StudySection(title: "43. No confundir prosperidad con aprobación", content: "La prosperidad no demuestra por sí sola mayor favor espiritual. La Biblia presenta fieles que atravesaron pruebas y advierte contra juzgar por apariencias.", references: "Job 1:1-3; Lc 16:19-31; 1 Ti 6:5"),
      StudySection(title: "44. Humildad ante los logros", content: "Los logros deben recibirse con gratitud, reconociendo que capacidades y oportunidades dependen de Dios. El éxito no autoriza despreciar a otros.", references: "Dt 8:17-18; 1 Co 4:7"),
      StudySection(title: "45. Mayordomía y justicia", content: "La administración fiel no se limita al beneficio privado; debe respetar la dignidad humana, evitar opresión y procurar relaciones justas.", references: "Mi 6:8; Pr 14:31"),
      StudySection(title: "46. Uso responsable de tecnología", content: "Las herramientas tecnológicas y medios deben utilizarse con prudencia, verdad y propósito, sin desplazar responsabilidades ni facilitar daño.", references: "Ef 5:15-16; Fil 4:8"),
      StudySection(title: "47. Equilibrio entre descanso y labor", content: "La responsabilidad no significa actividad ininterrumpida. El descanso reconoce los límites humanos y que la vida depende de Dios.", references: "Ex 20:8-11; Mr 6:31"),
      StudySection(title: "48. La mayordomía bajo el Dios trino", content: "El Padre es Creador y dueño, el Hijo es Señor y modelo de entrega, y el Espíritu capacita para servir. La vida se administra bajo la autoridad trinitaria.", references: "1 Co 8:6; Col 1:16-17; 1 Co 12:4-6"),
      StudySection(title: "49. Vivir para la gloria de Dios", content: "La finalidad no es acumular ni construir imagen personal, sino honrar a Dios en cada área de la vida.", references: "1 Co 10:31; Col 3:17"),
      StudySection(title: "50. Transmitir responsabilidad a la siguiente generación", content: "La fidelidad incluye enseñar a los más jóvenes a reconocer a Dios como dueño de todo y a usar con sabiduría lo que reciben.", references: "Dt 6:6-7; Sal 78:4-7"),
    ],
    conclusion: "La mayordomía cristiana es una responsabilidad integral que abarca mucho más que el dinero. El tiempo, las capacidades, el cuerpo, el trabajo, los recursos, las relaciones y la creación pertenecen a Dios y deben administrarse con fidelidad. La Biblia llama a la diligencia, la honestidad, la generosidad, la justicia, la moderación y la transparencia, sin convertir la prosperidad material en medida de espiritualidad. El creyente no sirve para comprar la salvación, sino porque ha recibido la gracia de Dios y desea honrarlo con toda su vida. La certeza de que rendirá cuentas al Señor debe producir humildad y constancia, no temor servil ni orgullo. Bajo la obra del Padre, del Hijo y del Espíritu Santo, cada responsabilidad cotidiana puede convertirse en servicio fiel. La pregunta decisiva no es cuánto se ha acumulado, sino si aquello que Dios confió ha sido administrado para el bien del prójimo y para la gloria de su nombre."
  ),
Study(
    number: '74',
    title: "El diseño bíblico de la familia: matrimonio, paternidad, crianza y relaciones bajo el señorío de Dios",
    subtitle: "Un estudio bíblico sobre el matrimonio, la paternidad, la crianza, el cuidado mutuo y la vida familiar bajo la autoridad de Dios.",
    introduction: "La familia ocupa un lugar importante en la enseñanza bíblica, desde el relato de la creación hasta las instrucciones apostólicas para la vida cotidiana. La Escritura presenta la dignidad del hombre y de la mujer, el matrimonio como pacto, la responsabilidad de los padres, la formación de los hijos y el cuidado de los familiares vulnerables. También reconoce que los hogares atraviesan conflictos, pérdidas y circunstancias difíciles, por lo que sus relaciones necesitan verdad, paciencia, justicia y gracia. Este estudio examina esos principios sin confundir la familia humana con la familia espiritual de Dios ni convertir una estructura social en medida del valor de las personas. Desde una perspectiva trinitaria, el Padre es fuente de toda familia creada, Jesucristo enseña el amor sacrificial y el Espíritu Santo produce el fruto necesario para una convivencia santa. El propósito es comprender cómo honrar a Dios en las relaciones familiares concretas.",
    sections: [
      StudySection(title: "1. La familia en el propósito creador", content: "La familia forma parte del orden de la creación y constituye un ámbito de compañía, responsabilidad y cuidado. Su comprensión debe partir de lo que Dios revela, no únicamente de las costumbres de cada época.", references: "Génesis 1:27-28; 2:18-24"),
      StudySection(title: "2. El hombre y la mujer como imagen de Dios", content: "Varón y mujer poseen igual dignidad porque ambos fueron creados a imagen de Dios. Las diferencias personales no autorizan desprecio, abuso ni desigualdad de valor.", references: "Génesis 1:26-27; Santiago 3:9"),
      StudySection(title: "3. La dignidad compartida", content: "La dignidad humana no depende del estado civil, la capacidad económica ni la posibilidad de tener hijos. Cada persona debe ser tratada con honra y justicia dentro de la familia.", references: "Génesis 1:27; Gálatas 3:28"),
      StudySection(title: "4. La compañía y la ayuda mutua", content: "La expresión de que no es bueno que el hombre esté solo presenta la compañía como parte del propósito creador. La relación familiar debe cultivar apoyo, responsabilidad y cuidado mutuo.", references: "Génesis 2:18"),
      StudySection(title: "5. El matrimonio como pacto", content: "La unión matrimonial se presenta como un compromiso de fidelidad y vida compartida. No debe reducirse a un acuerdo pasajero basado solamente en emociones o conveniencias.", references: "Génesis 2:24; Malaquías 2:14"),
      StudySection(title: "6. Dejar y unirse", content: "Génesis 2:24 describe el establecimiento de una nueva unidad familiar. Formar un hogar implica asumir responsabilidades propias y establecer límites sanos con las familias de origen.", references: "Génesis 2:24; Mateo 19:4-6"),
      StudySection(title: "7. Una sola carne", content: "La expresión una sola carne señala una unión profunda que comprende compromiso, intimidad y proyecto de vida. Jesús reafirma la seriedad de esta unión delante de Dios.", references: "Génesis 2:24; Mateo 19:5-6"),
      StudySection(title: "8. Fidelidad matrimonial", content: "La fidelidad protege la confianza y honra el pacto matrimonial. La Escritura llama a guardar el matrimonio y rechazar la infidelidad que hiere a las personas y destruye la confianza.", references: "Éxodo 20:14; Hebreos 13:4"),
      StudySection(title: "9. El amor dentro del matrimonio", content: "El amor matrimonial debe expresarse en entrega, consideración y servicio, no en egoísmo o dominio. El modelo de Cristo orienta una conducta que busca el bien del otro.", references: "Efesios 5:25-29; Colosenses 3:19"),
      StudySection(title: "10. Respeto y consideración mutua", content: "La vida matrimonial requiere respeto recíproco y disposición a escuchar. Ningún texto bíblico debe utilizarse para justificar humillación, amenazas o violencia.", references: "Efesios 5:21; 1 Pedro 3:7"),
      StudySection(title: "11. Responsabilidad del esposo", content: "El llamado al esposo es amar de manera sacrificial, cuidar y tratar a su esposa con honra. La autoridad nunca debe convertirse en abuso ni anular la dignidad de ella.", references: "Efesios 5:25-29; Colosenses 3:19"),
      StudySection(title: "12. Responsabilidad de la esposa", content: "La enseñanza apostólica llama a la esposa a actuar con respeto y fidelidad dentro del matrimonio. Este llamado debe leerse junto al mandato general de sumisión mutua y al amor sacrificial del esposo.", references: "Efesios 5:21-24,33; Colosenses 3:18"),
      StudySection(title: "13. La relación matrimonial y Cristo", content: "Pablo utiliza el matrimonio para ilustrar el amor de Cristo por la Iglesia. La comparación exige que el trato matrimonial refleje cuidado, entrega y fidelidad, nunca manipulación.", references: "Efesios 5:25-32"),
      StudySection(title: "14. El matrimonio y la santidad", content: "La intimidad matrimonial debe vivirse con fidelidad, respeto y pureza. La enseñanza bíblica presenta el cuerpo y la sexualidad como asuntos que deben honrar a Dios y proteger al cónyuge.", references: "Hebreos 13:4; 1 Corintios 7:3-5"),
      StudySection(title: "15. La comunicación en el hogar", content: "Hablar con verdad, escuchar con paciencia y evitar palabras destructivas fortalece las relaciones familiares. La comunicación cristiana debe edificar y buscar la reconciliación.", references: "Efesios 4:25,29; Santiago 1:19"),
      StudySection(title: "16. Resolver conflictos con humildad", content: "Los desacuerdos deben tratarse sin insultos ni violencia. La humildad permite reconocer errores, pedir perdón y buscar soluciones que respeten a todos los integrantes del hogar.", references: "Efesios 4:26-32; Colosenses 3:12-13"),
      StudySection(title: "17. El perdón en la familia", content: "El perdón cristiano se fundamenta en la misericordia recibida de Dios. No significa negar el daño ni impedir que se establezcan límites y se busque protección ante conductas abusivas.", references: "Efesios 4:32; Colosenses 3:13"),
      StudySection(title: "18. La soltería también tiene dignidad", content: "La Biblia no presenta el matrimonio como requisito para tener valor o servir a Dios. Pablo reconoce la soltería como una condición desde la cual también puede vivirse con fidelidad al Señor.", references: "1 Corintios 7:7-8,32-35"),
      StudySection(title: "19. El matrimonio no es salvación", content: "Estar casado no hace justo a nadie ni reemplaza la fe en Jesucristo. La salvación es por gracia y cada persona responde delante de Dios por su propia vida.", references: "Efesios 2:8-9; Romanos 14:12"),
      StudySection(title: "20. La decisión de casarse con sabiduría", content: "Las decisiones matrimoniales deben considerar la fe, el carácter, la responsabilidad y la compatibilidad de convicciones. La atracción por sí sola no basta para sostener un pacto.", references: "1 Corintios 7:39; Proverbios 19:2"),
      StudySection(title: "21. Los hijos como responsabilidad confiada", content: "Los hijos son personas con dignidad y no posesiones de sus padres. La crianza es una responsabilidad de cuidado, enseñanza y protección delante de Dios.", references: "Salmo 127:3-5; Marcos 10:13-16"),
      StudySection(title: "22. La responsabilidad de los padres", content: "Los padres están llamados a cuidar y formar a sus hijos con paciencia y constancia. La responsabilidad incluye atender necesidades materiales, emocionales, educativas y espirituales.", references: "Deuteronomio 6:6-7; Efesios 6:4"),
      StudySection(title: "23. Enseñar la Palabra en la vida cotidiana", content: "La formación espiritual no se limita a una reunión religiosa. Deuteronomio presenta la enseñanza de la Palabra integrada en las conversaciones y actividades diarias del hogar.", references: "Deuteronomio 6:6-9"),
      StudySection(title: "24. Instrucción con amor y paciencia", content: "La corrección debe procurar formación y madurez, no descargar ira. Los padres deben evitar provocar desaliento y deben instruir con paciencia y buen ejemplo.", references: "Efesios 6:4; Colosenses 3:21"),
      StudySection(title: "25. La disciplina sin violencia", content: "La disciplina bíblica busca enseñar responsabilidad y dominio propio. No autoriza maltrato, humillación ni daño; la corrección debe ser proporcionada, segura y respetuosa.", references: "Hebreos 12:10-11; Efesios 6:4"),
      StudySection(title: "26. El ejemplo de los padres", content: "Los hijos aprenden no solo por instrucciones, sino también al observar la conducta de los adultos. La coherencia entre palabras y acciones fortalece la enseñanza del hogar.", references: "Deuteronomio 6:6-7; Filipenses 4:9"),
      StudySection(title: "27. Escuchar a los hijos", content: "La crianza requiere escuchar y comprender, no solamente ordenar. La disposición a oír permite conocer necesidades, orientar con sabiduría y construir confianza.", references: "Santiago 1:19; Proverbios 18:13"),
      StudySection(title: "28. Proteger la dignidad y seguridad de los niños", content: "Los niños deben ser protegidos de abuso, explotación, negligencia y cualquier forma de violencia. Jesús mostró una actitud de acogida y cuidado hacia ellos.", references: "Mateo 18:5-6; 19:14"),
      StudySection(title: "29. La responsabilidad de los hijos", content: "La Escritura llama a los hijos a honrar y obedecer a sus padres en el Señor. Esta enseñanza no obliga a obedecer instrucciones que impliquen pecado o peligro.", references: "Efesios 6:1-3; Colosenses 3:20"),
      StudySection(title: "30. Honrar a los padres durante la vida", content: "Honrar a los padres incluye respeto, gratitud y consideración. En la adultez también puede expresarse mediante el cuidado responsable, sin permitir que se perpetúe el abuso.", references: "Éxodo 20:12; Marcos 7:9-13"),
      StudySection(title: "31. El cuidado de familiares vulnerables", content: "La fe debe expresarse en el cuidado de familiares que necesitan apoyo. La responsabilidad familiar no debe convertirse en abandono de personas vulnerables.", references: "1 Timoteo 5:4,8; Santiago 1:27"),
      StudySection(title: "32. La familia y el trabajo", content: "El trabajo y las responsabilidades del hogar deben organizarse con justicia y consideración. Ninguna búsqueda de éxito debe justificar el abandono del cuidado familiar.", references: "Colosenses 3:23; 1 Timoteo 5:8"),
      StudySection(title: "33. La administración de los recursos del hogar", content: "La familia necesita administrar sus recursos con honestidad, previsión y generosidad. Las decisiones económicas deben evitar la codicia y proteger las necesidades esenciales.", references: "Proverbios 21:5; 1 Timoteo 6:17-19"),
      StudySection(title: "34. La hospitalidad familiar", content: "El hogar puede convertirse en un espacio de acogida, servicio y generosidad. La hospitalidad cristiana no depende de la riqueza, sino de una disposición sincera para compartir.", references: "Romanos 12:13; Hebreos 13:2"),
      StudySection(title: "35. La oración y la vida espiritual del hogar", content: "La familia puede cultivar la oración y la lectura bíblica como prácticas de comunión con Dios. Estas actividades deben realizarse con sinceridad y no como una apariencia religiosa.", references: "Deuteronomio 6:6-7; Colosenses 4:2"),
      StudySection(title: "36. La fe no se impone mediante coerción", content: "Los padres pueden enseñar y dar ejemplo, pero cada persona debe responder a Dios con convicción. La manipulación y el temor no producen una fe auténtica.", references: "Josué 24:15; Romanos 14:12"),
      StudySection(title: "37. La familia frente a las diferencias", content: "Las diferencias de personalidad y opinión deben tratarse con paciencia y verdad. La unidad familiar no exige que todos piensen igual en asuntos secundarios.", references: "Romanos 12:16-18; Efesios 4:2-3"),
      StudySection(title: "38. El trato digno a los adultos mayores", content: "La vejez merece honra y consideración. La familia y la comunidad deben evitar el abandono y reconocer la experiencia y dignidad de las personas mayores.", references: "Levítico 19:32; 1 Timoteo 5:1-2"),
      StudySection(title: "39. La familia extendida y los límites sanos", content: "La relación con abuelos, tíos y otros parientes puede ser una fuente de apoyo, pero debe respetar las responsabilidades del nuevo hogar y los límites necesarios para la paz.", references: "Génesis 2:24; Romanos 12:18"),
      StudySection(title: "40. La familia en tiempos de dificultad", content: "Las enfermedades, pérdidas y crisis requieren compasión y apoyo. La familia no siempre puede resolver cada problema, pero puede acompañar y buscar ayuda sabia.", references: "Gálatas 6:2; Romanos 12:15"),
      StudySection(title: "41. El cuidado ante el conflicto y la violencia", content: "La violencia nunca debe justificarse como disciplina o autoridad. Quien está en peligro necesita protección y apoyo responsable; la reconciliación no exige permanecer en una situación dañina.", references: "Salmo 82:3-4; Proverbios 22:3"),
      StudySection(title: "42. La familia y la comunidad de fe", content: "La congregación puede apoyar a hogares y personas en distintas circunstancias, sin sustituir sus responsabilidades ni imponer una única estructura familiar como medida de dignidad.", references: "Gálatas 6:10; Romanos 12:13"),
      StudySection(title: "43. El testimonio del hogar", content: "La conducta familiar puede mostrar el efecto del evangelio mediante amor, justicia, servicio y dominio propio. El testimonio cristiano comienza también en las relaciones cotidianas.", references: "Mateo 5:16; Colosenses 3:12-17"),
      StudySection(title: "44. La crianza en un mundo cambiante", content: "Los padres deben formar criterio bíblico y enseñar a evaluar ideas, hábitos y contenidos con sabiduría. La formación requiere diálogo, acompañamiento y ejemplo coherente.", references: "Proverbios 4:1-7; Filipenses 4:8"),
      StudySection(title: "45. La responsabilidad compartida en el hogar", content: "Las tareas y responsabilidades domésticas deben distribuirse con justicia y consideración por las capacidades y circunstancias de cada integrante. El servicio mutuo fortalece la convivencia.", references: "Gálatas 5:13; Filipenses 2:3-4"),
      StudySection(title: "46. El valor de la vida familiar cotidiana", content: "Los actos ordinarios de cuidado, trabajo, escucha y servicio tienen valor delante de Dios. La fidelidad familiar se expresa en decisiones diarias, no solo en momentos extraordinarios.", references: "Colosenses 3:17,23; 1 Corintios 10:31"),
      StudySection(title: "47. La familia y la esperanza cristiana", content: "La esperanza de la familia no depende de una vida libre de problemas, sino de la fidelidad de Dios. La fe ayuda a perseverar, acompañarse y buscar consuelo en Cristo.", references: "Romanos 15:4,13; 1 Tesalonicenses 4:13-18"),
      StudySection(title: "48. El Dios trino y el fundamento del hogar", content: "El Padre es fuente de toda familia creada, el Hijo enseña el amor sacrificial y el Espíritu produce fruto para una convivencia santa. Esta relación no convierte a la familia humana en una réplica de la Trinidad, sino que orienta su vida hacia Dios.", references: "Efesios 3:14-15; Juan 15:9-12; Gálatas 5:22-23"),
      StudySection(title: "49. La familia como ámbito de servicio a Dios", content: "El hogar puede ser un lugar donde se practica la fe mediante hospitalidad, enseñanza, justicia, generosidad y servicio. Cada integrante puede honrar a Dios desde sus responsabilidades.", references: "Josué 24:15; Colosenses 3:17"),
      StudySection(title: "50. La gracia de Dios para familias imperfectas", content: "Ninguna familia humana es perfecta. El evangelio ofrece perdón, dirección y esperanza para reconocer errores, buscar ayuda, reparar relaciones cuando sea posible y crecer en obediencia a Dios.", references: "Romanos 3:23-24; 1 Juan 1:9; 2 Corintios 12:9"),
    ],
    conclusion: "La enseñanza bíblica sobre la familia comienza con la dignidad de cada persona creada a imagen de Dios y continúa con responsabilidades de amor, fidelidad, cuidado y servicio. El matrimonio es un pacto que requiere compromiso y respeto; la crianza exige paciencia, instrucción y protección; los hijos son llamados a honrar a sus padres; y todos los integrantes del hogar deben procurar relaciones marcadas por la verdad y la misericordia. Ningún pasaje bíblico debe utilizarse para justificar abuso, violencia o humillación. La familia humana no es perfecta ni reemplaza la salvación en Cristo, pero puede convertirse en un ámbito donde se manifiesten la gracia y la obediencia a Dios. El Padre, el Hijo y el Espíritu Santo orientan al creyente a vivir con amor, justicia y santidad, para que aun en las tareas cotidianas el hogar honre al Señor.",
  ),
Study(
    number: '75',
    title: "El estado intermedio: la condición del ser humano entre la muerte y la resurrección final",
    subtitle: "Un estudio bíblico y trinitario sobre la condición humana entre la muerte física y la resurrección final, con atención a los textos, sus contextos y los límites de la revelación.",
    introduction: "La muerte es una realidad que atraviesa la experiencia humana, pero la fe cristiana no la considera el destino definitivo de quienes pertenecen a Jesucristo. La Escritura enseña que habrá resurrección, juicio y consumación del propósito de Dios. Entre la muerte física y la resurrección final existe un período que la teología denomina estado intermedio. Para estudiarlo es necesario examinar pasajes como Lucas 23:43, Filipenses 1:21-23, 2 Corintios 5:1-8, Juan 5:28-29 y 1 Tesalonicenses 4:13-18, sin aislarlos de la enseñanza bíblica completa. Los cristianos han sostenido distintas interpretaciones acerca de la conciencia después de la muerte; por ello, este estudio distinguirá las afirmaciones explícitas de la Escritura de las conclusiones debatidas, evitando especulaciones. La esperanza central no está en dominar los detalles del mundo invisible, sino en Jesucristo, quien murió, resucitó y levantará a los suyos. El Padre sostiene su propósito, el Hijo tiene autoridad sobre la vida y la muerte, y el Espíritu Santo es garantía de la redención futura.",
    sections: [
      StudySection(title: "1. La muerte y la esperanza bíblica", content: "La muerte es real, pero no es el destino definitivo de quienes pertenecen a Cristo. La esperanza cristiana mira hacia la resurrección y la consumación de la obra redentora.", references: "Hebreos 9:27; 1 Corintios 15:20-23"),
      StudySection(title: "2. Definición del estado intermedio", content: "Se denomina estado intermedio al período entre la muerte física y la resurrección final. Es una categoría teológica que organiza diversos textos, no una expresión técnica bíblica.", references: "Lucas 23:43; Filipenses 1:21-23; 1 Corintios 15:51-54"),
      StudySection(title: "3. Muerte y resurrección son distintas", content: "La muerte física y la resurrección son acontecimientos diferentes. La enseñanza apostólica anuncia que los muertos serán levantados y los creyentes transformados cuando Cristo venga.", references: "Juan 5:28-29; 1 Tesalonicenses 4:13-17"),
      StudySection(title: "4. La naturaleza corporal del ser humano", content: "La creación humana incluye el cuerpo. La esperanza bíblica no consiste en despreciarlo, sino en esperar la redención completa de la persona.", references: "Génesis 2:7; Romanos 8:23; 1 Corintios 15:42-44"),
      StudySection(title: "5. La muerte como consecuencia del pecado", content: "La muerte entró en la experiencia humana por el pecado. Cristo es presentado como aquel que venció la muerte y ofrece vida a quienes están unidos a él.", references: "Génesis 3:19; Romanos 5:12; 1 Corintios 15:21-22"),
      StudySection(title: "6. La victoria de Jesucristo", content: "La resurrección de Jesús fundamenta la esperanza futura. El Hijo venció la muerte y garantiza la resurrección de los suyos.", references: "Juan 11:25-26; 1 Corintios 15:20-22"),
      StudySection(title: "7. La promesa al malhechor arrepentido", content: "En la cruz, Jesús prometió al malhechor arrepentido estar con él en el paraíso. El texto es relevante y debe leerse considerando su contexto y las cuestiones de puntuación textual.", references: "Lucas 23:39-43"),
      StudySection(title: "8. Pablo desea estar con Cristo", content: "Pablo expresa su deseo de partir y estar con Cristo, lo cual considera muchísimo mejor. El pasaje es central en el debate sobre la comunión con Cristo después de morir.", references: "Filipenses 1:21-23"),
      StudySection(title: "9. Ausentes del cuerpo y presentes al Señor", content: "Pablo contrasta la vida presente en el cuerpo con estar presentes al Señor. Este pasaje ofrece consuelo y debe leerse junto con la enseñanza sobre la resurrección futura.", references: "2 Corintios 5:1-8"),
      StudySection(title: "10. La comunión con Cristo como esperanza", content: "La esperanza no descansa en conocer cada detalle del más allá, sino en pertenecer a Cristo. La muerte no puede separar al creyente del amor de Dios.", references: "Romanos 8:35-39"),
      StudySection(title: "11. El lenguaje bíblico del sueño", content: "Diversos pasajes describen la muerte mediante la figura del sueño. Esta imagen destaca la temporalidad de la muerte frente al despertar que Dios realizará.", references: "Daniel 12:2; Juan 11:11-14; 1 Tesalonicenses 4:13-15"),
      StudySection(title: "12. El sueño y la esperanza de resurrección", content: "La figura del sueño no debe aislarse para negar otros textos. Jesús habló de la resurrección y Pablo anunció que los muertos en Cristo resucitarán.", references: "Juan 5:28-29; 1 Corintios 15:51-54"),
      StudySection(title: "13. Dormir en Cristo", content: "Pablo llama a los creyentes fallecidos los que durmieron en Cristo. La expresión une la realidad de la muerte con la esperanza de que Dios los levantará.", references: "1 Corintios 15:18; 1 Tesalonicenses 4:14"),
      StudySection(title: "14. Dios sostiene frente a la muerte", content: "Los salmos presentan a Dios como refugio y pastor incluso ante la muerte. La confianza no depende de conocer todos los detalles del estado intermedio.", references: "Salmos 23:4-6; 139:7-12"),
      StudySection(title: "15. La promesa de vida eterna", content: "Jesús promete vida eterna a quienes creen en él. Esta vida comienza en la relación con el Hijo y alcanza su consumación en la resurrección final.", references: "Juan 5:24-29; 6:39-40"),
      StudySection(title: "16. La resurrección en el día final", content: "Jesús enseña que levantará a los suyos en el día final. La esperanza no se reduce a una existencia desencarnada e indefinida.", references: "Juan 6:39-40,44,54"),
      StudySection(title: "17. La resurrección corporal", content: "Pablo explica que el cuerpo resucitado será transformado: lo corruptible será revestido de incorrupción. La transformación corporal es parte de la esperanza bíblica.", references: "1 Corintios 15:35-54"),
      StudySection(title: "18. La transformación de los creyentes vivos", content: "La venida de Cristo transformará también a quienes estén vivos. La esperanza comprende a los muertos en Cristo y a quienes permanezcan hasta su manifestación.", references: "1 Corintios 15:51-53; 1 Tesalonicenses 4:15-17"),
      StudySection(title: "19. La reunión con el Señor", content: "Pablo consuela a la Iglesia con la promesa de que los creyentes estarán para siempre con el Señor. El centro de la esperanza es la comunión definitiva con Jesús.", references: "1 Tesalonicenses 4:16-18"),
      StudySection(title: "20. La esperanza expresada por Job", content: "Job expresa confianza en que verá a su Redentor. Aunque el pasaje tiene dificultades interpretativas, comunica esperanza en la vindicación final de Dios.", references: "Job 19:25-27"),
      StudySection(title: "21. El despertar anunciado por Daniel", content: "Daniel anuncia que muchos de los que duermen en el polvo despertarán. El texto vincula la muerte con una resurrección futura y con destinos distintos.", references: "Daniel 12:1-3"),
      StudySection(title: "22. Los mártires y la justicia divina", content: "Apocalipsis presenta a los mártires clamando por justicia. La visión comunica que Dios conoce el sufrimiento de sus siervos y no olvida su fidelidad.", references: "Apocalipsis 6:9-11"),
      StudySection(title: "23. La multitud ante el trono", content: "Apocalipsis describe una multitud ante el trono de Dios y del Cordero. La visión proclama la salvación divina, sin ofrecer un esquema exhaustivo de cada condición temporal después de morir.", references: "Apocalipsis 7:9-17"),
      StudySection(title: "24. El paraíso en el lenguaje apostólico", content: "Pablo menciona haber sido arrebatado al paraíso en una experiencia extraordinaria. El término aparece en la Escritura, pero no autoriza especulaciones fuera de lo revelado.", references: "2 Corintios 12:2-4"),
      StudySection(title: "25. El altar y los mártires", content: "La visión de las almas de los mártires bajo el altar emplea lenguaje apocalíptico. Debe interpretarse atendiendo al género literario y al mensaje de justicia y vindicación.", references: "Apocalipsis 6:9-11"),
      StudySection(title: "26. El rico y Lázaro", content: "Jesús presenta destinos posteriores a la muerte en una parábola que subraya la urgencia de escuchar la Palabra. Su propósito principal no es responder cada pregunta sobre el más allá.", references: "Lucas 16:19-31"),
      StudySection(title: "27. Los límites de la revelación", content: "La enseñanza sobre los muertos debe permanecer dentro de lo que Dios ha revelado. No corresponde convertir visiones y símbolos en mapas completos del mundo invisible.", references: "Deuteronomio 29:29; 2 Timoteo 3:16-17"),
      StudySection(title: "28. Diferencias interpretativas cristianas", content: "Existen distintas explicaciones cristianas sobre la conciencia después de la muerte. El estudio responsable presenta los textos, reconoce las diferencias y no afirma como explícito lo que el pasaje no define.", references: "Filipenses 1:21-23; 2 Corintios 5:1-8; 1 Tesalonicenses 4:13-17"),
      StudySection(title: "29. Evitar especulaciones", content: "La curiosidad no debe desplazar las verdades centrales: Cristo murió, resucitó, volverá y levantará a los muertos. La doctrina debe producir esperanza y fidelidad.", references: "1 Corintios 15:1-4,12-20; Colosenses 2:18-19"),
      StudySection(title: "30. La muerte no separa de Cristo", content: "Pablo afirma que ni la muerte ni la vida pueden separar al creyente del amor de Dios en Cristo. La seguridad descansa en la fidelidad del Señor.", references: "Romanos 8:38-39"),
      StudySection(title: "31. El consuelo en el duelo", content: "La Iglesia no debe negar el dolor. Jesús lloró ante la tumba de Lázaro y acompañó a quienes sufrían, mostrando que la esperanza es compatible con el duelo sincero.", references: "Juan 11:32-36; 1 Tesalonicenses 4:13-18"),
      StudySection(title: "32. La muerte de los santos ante Dios", content: "El salmista declara que la muerte de los santos es estimada delante del Señor. La vida de quienes pertenecen a Dios no cae en el olvido.", references: "Salmos 116:15"),
      StudySection(title: "33. No consultar a los muertos", content: "La Escritura prohíbe buscar dirección espiritual mediante prácticas de consulta a los muertos. La confianza del creyente debe dirigirse a Dios y a su Palabra.", references: "Deuteronomio 18:10-12; Isaías 8:19-20"),
      StudySection(title: "34. Cristo, único mediador", content: "La esperanza no depende de intermediarios humanos ni de rituales para controlar el destino de los difuntos. Jesucristo es el único mediador entre Dios y los seres humanos.", references: "1 Timoteo 2:5; Hebreos 7:24-25"),
      StudySection(title: "35. El Espíritu como garantía", content: "El Espíritu Santo es sello y garantía de la herencia prometida. Su presencia confirma que la obra de Dios llegará a su cumplimiento en la redención final.", references: "Efesios 1:13-14; Romanos 8:11,23"),
      StudySection(title: "36. El Padre, fuente de esperanza", content: "El Padre es presentado como Dios que resucita a los muertos y sostiene la esperanza de su pueblo. La vida futura descansa en su propósito fiel.", references: "2 Corintios 1:9; Romanos 6:4"),
      StudySection(title: "37. El Hijo tiene autoridad sobre la muerte", content: "Jesús declara tener autoridad para dar vida y llama a los muertos a salir de sus sepulcros. La esperanza cristiana está centrada en la persona y autoridad del Hijo.", references: "Juan 5:21-29; Apocalipsis 1:17-18"),
      StudySection(title: "38. La obra del Dios trino en la resurrección", content: "El Nuevo Testamento relaciona la resurrección con la acción de Dios, la autoridad del Hijo y la vivificación por el Espíritu. La esperanza revela la obra unida del Dios trino.", references: "Romanos 8:11; Juan 5:21; 1 Pedro 1:3-5"),
      StudySection(title: "39. Resurrección y juicio", content: "La Escritura relaciona la resurrección con el juicio de Dios. La humanidad comparecerá ante el Señor y su justicia será manifestada plenamente.", references: "Juan 5:28-29; Hechos 24:15; Apocalipsis 20:11-13"),
      StudySection(title: "40. La nueva creación", content: "La meta final no es una existencia incompleta, sino la renovación de todas las cosas. Dios promete cielos nuevos y tierra nueva donde habitará la justicia.", references: "Isaías 65:17; 2 Pedro 3:13; Apocalipsis 21:1-5"),
      StudySection(title: "41. La muerte será destruida", content: "La promesa final anuncia que la muerte será destruida y que Dios enjugará toda lágrima. La muerte no tendrá la última palabra sobre la creación redimida.", references: "1 Corintios 15:25-26; Apocalipsis 21:4"),
      StudySection(title: "42. La esperanza transforma la vida", content: "Esperar la resurrección no conduce a la pasividad. Pablo llama a permanecer firmes y abundar en la obra del Señor.", references: "1 Corintios 15:58; Tito 2:11-13"),
      StudySection(title: "43. Santidad ante la eternidad", content: "La esperanza futura impulsa pureza y obediencia. Quien espera al Señor procura vivir de manera coherente con la promesa recibida.", references: "1 Juan 3:2-3; 2 Pedro 3:11-14"),
      StudySection(title: "44. La misión de la Iglesia", content: "La realidad de la muerte recuerda a la Iglesia la urgencia de anunciar el evangelio y acompañar a quienes sufren. La proclamación ofrece esperanza en la resurrección de Jesús.", references: "Mateo 28:19-20; 2 Corintios 5:18-20"),
      StudySection(title: "45. Consuelo mutuo", content: "Pablo manda que los creyentes se consuelen con la promesa de la venida del Señor y la reunión de su pueblo. La doctrina tiene una función pastoral concreta.", references: "1 Tesalonicenses 4:18; 5:11"),
      StudySection(title: "46. La fidelidad de Dios sostiene la esperanza", content: "La confianza no depende de resolver cada detalle del estado intermedio. Se apoya en el carácter fiel de Dios y en las promesas confirmadas por la resurrección de Jesús.", references: "Hebreos 10:23; 1 Pedro 1:3-5"),
      StudySection(title: "47. Estado intermedio y estado eterno", content: "El estado intermedio es temporal y debe distinguirse de la consumación final. La Biblia sitúa resurrección, juicio y nueva creación en el horizonte definitivo.", references: "1 Corintios 15:20-26; Apocalipsis 20:11-15; 21:1-4"),
      StudySection(title: "48. La esperanza centrada en Cristo", content: "La pregunta decisiva no es satisfacer toda curiosidad sobre el mundo invisible, sino pertenecer a Jesucristo. Él es la resurrección y la vida.", references: "Juan 11:25-26; Filipenses 3:20-21"),
      StudySection(title: "49. Vivir y morir para el Señor", content: "Pablo enseña que tanto la vida como la muerte del creyente pertenecen al Señor. Esta convicción da sentido a la existencia presente y esperanza ante la muerte.", references: "Romanos 14:7-9"),
      StudySection(title: "50. La consumación de la esperanza trinitaria", content: "El Padre cumplirá su propósito, el Hijo levantará a los suyos y el Espíritu vivificará sus cuerpos. La esperanza descansa en el Dios trino y culmina en comunión eterna con él.", references: "Romanos 8:11,23; Juan 6:40; 1 Corintios 15:24-28"),
    ],
    conclusion: "El estado intermedio debe estudiarse a la luz de toda la enseñanza bíblica y con humildad ante aquello que Dios no ha revelado por completo. Los textos ofrecen consuelo y esperanza, pero no autorizan a construir descripciones detalladas más allá de su propósito. La verdad fundamental es que la muerte no separa al creyente del amor de Dios en Cristo, y que la esperanza cristiana no termina en una existencia incompleta: espera la resurrección corporal, el juicio justo y la nueva creación. Jesucristo es la resurrección y la vida; el Padre cumplirá su propósito y el Espíritu vivificará a los que pertenecen al Señor. Por eso, esta doctrina debe producir consuelo en el duelo, santidad, perseverancia, servicio y confianza en las promesas divinas. La Iglesia anuncia con seguridad lo que Dios ha dicho y mantiene reverencia donde la Escritura guarda silencio, esperando la consumación de la salvación para gloria del Padre, del Hijo y del Espíritu Santo."
  ),
Study(
    number: '76',
    title: "La Cena del Señor: institución, significado del nuevo pacto, comunión y esperanza del regreso de Cristo",
    subtitle: "Un estudio bíblico sobre la institución de la Cena del Señor, su significado en el nuevo pacto, la comunión de la Iglesia y la esperanza del regreso de Jesucristo.",
    introduction: "La Cena del Señor fue instituida por Jesucristo y entregada a sus discípulos como una práctica de memoria, proclamación y comunión. El pan y la copa remiten al cuerpo entregado y a la sangre del nuevo pacto, anunciando la muerte del Señor hasta que él venga. La enseñanza apostólica muestra que esta celebración no debe convertirse en un rito vacío, un acto mágico, una repetición del sacrificio de Cristo ni una ocasión de división social o espiritual. La Cena llama a recordar con fe, examinarse, discernir el cuerpo, vivir en unidad y esperar la consumación del reino. Este estudio desarrolla su institución en el contexto de la Pascua, su fundamento en la obra suficiente de Cristo, su dimensión congregacional, las correcciones de Pablo a la iglesia de Corinto y su orientación hacia el regreso del Señor. También distingue la Cena del bautismo y considera la participación del Padre, del Hijo y del Espíritu Santo en la comunión del pueblo redimido.",
    sections: [
      StudySection(title: "1. Instituida por Jesucristo", content: "La Cena fue establecida por instrucción directa del Señor Jesús durante su última cena con los discípulos. Su práctica debe permanecer ligada a sus palabras y propósito.", references: "Mateo 26:26-29; Lucas 22:14-20"),
      StudySection(title: "2. El contexto de la última cena", content: "Jesús instituyó esta ordenanza en el contexto de la Pascua y dirigió la atención hacia su entrega y el cumplimiento del propósito redentor de Dios.", references: "Mateo 26:17-20; Lucas 22:7-16"),
      StudySection(title: "3. La Pascua y su cumplimiento en Cristo", content: "La Pascua recordaba la liberación de Israel de Egipto. Jesús relacionó su muerte con una liberación mayor y con el cumplimiento de las promesas de Dios.", references: "Éxodo 12:1-14; Lucas 22:14-20; 1 Corintios 5:7"),
      StudySection(title: "4. El pan tomado por Jesús", content: "Jesús tomó el pan, dio gracias, lo partió y lo entregó a sus discípulos. Sus palabras establecen el sentido memorial de la ordenanza.", references: "Mateo 26:26; Marcos 14:22"),
      StudySection(title: "5. El significado del pan", content: "El pan señala el cuerpo de Cristo entregado por nosotros. La Iglesia recuerda la entrega real del Hijo y proclama el evangelio de su sacrificio.", references: "Lucas 22:19; 1 Corintios 11:23-24"),
      StudySection(title: "6. La copa y la sangre del pacto", content: "Jesús relacionó la copa con su sangre derramada. Su muerte establece el fundamento del nuevo pacto prometido por Dios.", references: "Mateo 26:27-28; Jeremías 31:31-34"),
      StudySection(title: "7. El nuevo pacto en la sangre de Cristo", content: "El perdón y la reconciliación se fundamentan en la obra sacrificial de Jesús. Su entrega cumple la promesa del nuevo pacto.", references: "Lucas 22:20; Hebreos 8:6-13; 9:15"),
      StudySection(title: "8. Memorial de la obra de Cristo", content: "Jesús mandó hacer esto en memoria de él. La Cena dirige la memoria de la Iglesia hacia su persona, su muerte y el significado salvador de su entrega.", references: "Lucas 22:19; 1 Corintios 11:24-25"),
      StudySection(title: "9. Anunciar la muerte del Señor", content: "Cada vez que la Iglesia participa, anuncia la muerte del Señor hasta que él venga. La Cena es una proclamación visible del evangelio.", references: "1 Corintios 11:26"),
      StudySection(title: "10. La Cena no repite el sacrificio", content: "El sacrificio de Jesús fue ofrecido una vez y es suficiente. La Cena recuerda y proclama esa obra consumada; no añade otro sacrificio ni repite la crucifixión.", references: "Hebreos 9:24-28; 10:10-14"),
      StudySection(title: "11. La suficiencia de la cruz", content: "La confianza del creyente descansa en la obra completa de Jesucristo. Ningún acto litúrgico puede completar el sacrificio perfecto del Hijo.", references: "Juan 19:30; Hebreos 10:12-14"),
      StudySection(title: "12. La participación de la congregación", content: "La Cena es una práctica de la comunidad reunida. Su dimensión corporativa recuerda que los creyentes participan de un mismo Señor y forman un solo cuerpo.", references: "1 Corintios 10:16-17; 11:18-20"),
      StudySection(title: "13. Comunión con Cristo", content: "Pablo habla de la participación en el cuerpo y la sangre de Cristo. La Cena expresa comunión con el Señor y debe comprenderse a la luz de la fe.", references: "1 Corintios 10:16"),
      StudySection(title: "14. Un solo pan y un solo cuerpo", content: "Participar de un mismo pan señala la unidad de la Iglesia. No es coherente acercarse a la mesa mientras se alimentan divisiones o rivalidades.", references: "1 Corintios 10:17; 11:18-22"),
      StudySection(title: "15. Unidad y diversidad en la Iglesia", content: "La comunión de la mesa no exige idénticas funciones o circunstancias. Sí exige reconocer que todos dependen de Cristo y deben tratarse con amor y dignidad.", references: "Romanos 12:4-5; 1 Corintios 12:12-27"),
      StudySection(title: "16. Corrección de los abusos en Corinto", content: "Pablo corrigió las divisiones y comportamientos egoístas que deshonraban la Cena. La práctica externa contradice su propósito cuando se desprecia a otros creyentes.", references: "1 Corintios 11:17-22"),
      StudySection(title: "17. Esperar a los demás", content: "La instrucción de esperarse unos a otros muestra que la Cena no debía convertirse en una comida de privilegio para algunos. La consideración mutua forma parte de su celebración.", references: "1 Corintios 11:21-22,33"),
      StudySection(title: "18. Examinarse a uno mismo", content: "Pablo llama a cada participante a examinarse. Esto implica reconocer la seriedad de la ordenanza, revisar la propia conducta y acercarse con fe y reverencia.", references: "1 Corintios 11:27-28"),
      StudySection(title: "19. Discernir el cuerpo", content: "La advertencia sobre no discernir el cuerpo exige tomar en serio lo que la Cena significa y la comunidad que participa. No debe reducirse a un gesto automático.", references: "1 Corintios 11:29"),
      StudySection(title: "20. Reverencia sin terror servil", content: "Participar con reverencia significa reconocer la santidad de Cristo y el significado de su sacrificio. No significa creer que la gracia se obtiene por miedo o mérito ceremonial.", references: "Hebreos 4:14-16; 1 Corintios 11:27-29"),
      StudySection(title: "21. Confesión y arrepentimiento", content: "La mesa invita a una respuesta sincera ante Dios. Quien reconoce su pecado debe acudir a Cristo con arrepentimiento y fe, buscando vivir conforme al evangelio.", references: "1 Juan 1:7-9; 1 Corintios 11:28"),
      StudySection(title: "22. La Cena y el perdón", content: "La Cena recuerda que el perdón se fundamenta en la sangre de Cristo. No debe presentarse como mecanismo automático al margen de la fe y el arrepentimiento.", references: "Mateo 26:28; Efesios 1:7"),
      StudySection(title: "23. La Cena y la fe", content: "La participación debe expresar confianza en Jesucristo y su obra. El acto externo no reemplaza la fe ni convierte los elementos en garantía independiente de la gracia.", references: "Romanos 5:1; 1 Corintios 11:26"),
      StudySection(title: "24. La Cena y la gracia", content: "La mesa anuncia una salvación recibida por gracia. Participar no es pagar por el favor divino, sino recordar agradecidamente lo que Cristo hizo.", references: "Efesios 2:8-9; 1 Corintios 11:24-26"),
      StudySection(title: "25. La Cena y la gratitud", content: "Jesús dio gracias antes de repartir el pan y la copa. La gratitud debe caracterizar la celebración porque recuerda el amor de Dios demostrado en Cristo.", references: "Mateo 26:26-27; Colosenses 3:15-17"),
      StudySection(title: "26. La Cena y el amor fraternal", content: "La mesa confronta el egoísmo y llama a reconocer las necesidades de otros. La comunión con Cristo debe expresarse en servicio y cuidado de los hermanos.", references: "Juan 13:1-17; 1 Corintios 11:20-22"),
      StudySection(title: "27. La Cena y la reconciliación", content: "La unidad alrededor de Cristo exige buscar la paz y atender responsablemente los conflictos. La ordenanza no debe usarse para ocultar divisiones persistentes.", references: "Mateo 5:23-24; Efesios 4:1-3"),
      StudySection(title: "28. La mesa y la santidad de la Iglesia", content: "La comunión cristiana está llamada a reflejar la santidad de Dios. La Cena no aprueba el pecado persistente ni reemplaza la disciplina bíblica restauradora.", references: "1 Corintios 5:6-8; 11:27-32"),
      StudySection(title: "29. La disciplina y la restauración", content: "Pablo explica que la corrección del Señor busca que su pueblo no sea condenado con el mundo. La disciplina debe conducir al arrepentimiento, no a la humillación.", references: "1 Corintios 11:31-32; Gálatas 6:1"),
      StudySection(title: "30. La Cena y la esperanza futura", content: "Jesús habló de un cumplimiento futuro en el reino de su Padre. La Cena mira hacia atrás, al sacrificio de la cruz, y hacia adelante, a la consumación del reino.", references: "Mateo 26:29; Lucas 22:16-18"),
      StudySection(title: "31. Hasta que Cristo venga", content: "La Iglesia celebra la Cena mientras espera el regreso del Señor. La ordenanza mantiene viva la esperanza y recuerda que Cristo cumplirá sus promesas.", references: "1 Corintios 11:26; Tito 2:13"),
      StudySection(title: "32. El banquete del reino", content: "La Biblia presenta la consumación como celebración de comunión con Dios. La Cena anticipa la plenitud del reino y la presencia del Señor.", references: "Mateo 8:11; Apocalipsis 19:6-9"),
      StudySection(title: "33. La nueva comunidad del pacto", content: "La mesa identifica a una comunidad que vive bajo el nuevo pacto inaugurado por Cristo. La Iglesia debe reflejar la gracia, fidelidad y unidad recibidas.", references: "Jeremías 31:31-34; Hebreos 12:22-24"),
      StudySection(title: "34. La relación entre Cena y bautismo", content: "El bautismo identifica públicamente al discípulo con Cristo, mientras la Cena recuerda y proclama su sacrificio en la vida congregacional. Son prácticas distintas.", references: "Mateo 28:19; Lucas 22:19-20; Hechos 2:41-42"),
      StudySection(title: "35. La Cena en la Iglesia primitiva", content: "Los primeros creyentes perseveraban en la enseñanza apostólica, la comunión, el partimiento del pan y las oraciones. La mesa formaba parte de la vida compartida.", references: "Hechos 2:42,46; 20:7"),
      StudySection(title: "36. La frecuencia de la celebración", content: "El Nuevo Testamento muestra a la Iglesia participando de la Cena, pero no fija en todos los pasajes una frecuencia universal. La congregación debe actuar con fidelidad y orden.", references: "Hechos 2:42; 20:7; 1 Corintios 11:25-26"),
      StudySection(title: "37. Los elementos y su significado", content: "El pan y la copa deben comprenderse desde las palabras de Jesús y la enseñanza apostólica. Su significado está ligado a la entrega de Cristo.", references: "Mateo 26:26-28; 1 Corintios 11:23-26"),
      StudySection(title: "38. Evitar afirmaciones que excedan la Escritura", content: "Las tradiciones cristianas han explicado de diversas maneras la relación entre los elementos y Cristo. La Iglesia debe exponer con precisión los textos y no afirmar más de lo revelado.", references: "Lucas 22:19-20; 1 Corintios 10:16-17; 11:23-26"),
      StudySection(title: "39. La Cena no es un acto mágico", content: "La participación no actúa automáticamente sin fe, discernimiento ni obediencia. La confianza está en Cristo y su obra, no en una fórmula ceremonial.", references: "1 Corintios 11:27-29; Hebreos 10:19-22"),
      StudySection(title: "40. La Cena proclama el evangelio", content: "El pan y la copa ofrecen una proclamación visible de la muerte del Señor. La celebración debe acompañarse de enseñanza clara para que su significado sea comprendido.", references: "1 Corintios 11:26; Romanos 10:14-17"),
      StudySection(title: "41. Responsabilidad de quienes sirven", content: "Quienes preparan y administran la celebración deben hacerlo con reverencia, claridad y consideración. El liderazgo no debe usar la mesa para favoritismo o control.", references: "1 Corintios 11:20-22,33-34; 1 Pedro 5:2-3"),
      StudySection(title: "42. La participación y la conciencia", content: "La Iglesia debe enseñar con claridad cómo participar, evitando reglas arbitrarias y también la indiferencia ante las instrucciones apostólicas. La orientación pastoral debe fundarse en la Escritura.", references: "1 Corintios 11:27-29; Romanos 14:1-4"),
      StudySection(title: "43. La mesa no crea clases de creyentes", content: "La Cena no debe convertirse en símbolo de superioridad social, económica o ministerial. En Cristo, la comunidad rechaza el favoritismo y honra a todos.", references: "Santiago 2:1-9; 1 Corintios 11:21-22"),
      StudySection(title: "44. La Cena y el servicio de Cristo", content: "El Señor que instituyó la mesa también lavó los pies de sus discípulos. La memoria de su entrega llama a servir con humildad, no a buscar posiciones de honor.", references: "Juan 13:1-17; Marcos 10:42-45"),
      StudySection(title: "45. La Cena y la obra del Espíritu Santo", content: "El Espíritu forma y fortalece la comunión del pueblo de Dios. La celebración debe vivirse en dependencia del Espíritu, quien dirige a la Iglesia a glorificar a Cristo.", references: "1 Corintios 12:13; Efesios 4:3-4; Juan 16:14"),
      StudySection(title: "46. El Padre recibe gloria por medio del Hijo", content: "La Cena anuncia la obra del Hijo conforme al propósito salvador del Padre. La gratitud de la Iglesia debe conducir a glorificar a Dios por Jesucristo.", references: "Juan 6:38-40; Efesios 1:3-7; 1 Corintios 11:26"),
      StudySection(title: "47. La mesa y la unidad del Dios trino", content: "El Padre llama y salva, el Hijo entrega su vida y el Espíritu une a los creyentes. La Cena proclama la obra de Cristo dentro de la comunión trinitaria.", references: "Efesios 2:18-22; 1 Corintios 10:16-17"),
      StudySection(title: "48. La Cena como memoria activa", content: "Recordar a Cristo no es un ejercicio vacío del pasado. La memoria bíblica lleva a confesar su señorío, vivir en obediencia y anunciar su obra.", references: "Lucas 22:19; 1 Corintios 11:26; Colosenses 3:1-4"),
      StudySection(title: "49. Una celebración que edifica", content: "La Cena debe contribuir al crecimiento de la comunidad cuando se celebra con comprensión, amor, orden y fidelidad a la enseñanza apostólica.", references: "1 Corintios 10:17; 14:26; 11:33"),
      StudySection(title: "50. La esperanza sostiene a la Iglesia", content: "Cada celebración recuerda que Cristo volverá y que su pueblo no espera en vano. La mesa fortalece fe, unidad y perseverancia mientras la Iglesia aguarda su venida.", references: "1 Corintios 11:26; Apocalipsis 22:20"),
    ],
    conclusion: "La Cena del Señor es una ordenanza instituida por Jesucristo para que su Iglesia recuerde y proclame su sacrificio hasta que él vuelva. El pan y la copa señalan su cuerpo entregado y su sangre del nuevo pacto; no repiten ni completan la obra perfecta de la cruz. La participación debe realizarse con fe, reverencia, examen personal, discernimiento y amor fraternal. La mesa no admite orgullo, favoritismo ni divisiones, porque quienes participan confiesan a un mismo Señor y forman un solo cuerpo. La Cena mira al pasado, anunciando la muerte de Cristo; al presente, fortaleciendo la comunión y el servicio; y al futuro, esperando el banquete del reino. En la obra del Dios trino, el Padre cumple su propósito salvador, el Hijo entrega su vida y el Espíritu une y edifica a la Iglesia. Por eso, cada celebración debe conducir a gratitud, fidelidad y esperanza, para gloria de Dios por medio de Jesucristo.",
  ),
Study(
    number: '77',
    title: "La segunda venida de Jesucristo: promesa, propósito, esperanza y preparación de la Iglesia",
    subtitle: "Un estudio bíblico sobre la promesa del regreso glorioso de Jesucristo, su propósito, la esperanza de la Iglesia y la preparación fiel de los creyentes.",
    introduction: "La segunda venida de Jesucristo es una esperanza central del Nuevo Testamento. El mismo Señor que murió, resucitó y ascendió prometió volver, y los apóstoles enseñaron a la Iglesia a esperar ese acontecimiento con fe, paciencia y santidad. La doctrina no fue dada para alimentar cálculos de fechas, rumores o temor constante, sino para consolar a los creyentes, afirmar la justicia de Dios, fortalecer la perseverancia y orientar la vida presente. Este estudio examina las promesas de Jesús, el testimonio apostólico, la reunión de los creyentes con el Señor, la resurrección vinculada a su venida, el juicio y la consumación de la esperanza cristiana. También considera las advertencias contra los falsos cristos, el engaño y la especulación profética. Desde la perspectiva trinitaria, el Padre establece su propósito, el Hijo volverá con gloria y el Espíritu sostiene a la Iglesia en la esperanza. La respuesta bíblica es vivir fielmente mientras aguardamos al Señor.",
    sections: [
      StudySection(title: "1. La promesa del regreso", content: "Jesús prometió que volvería. La esperanza cristiana no se apoya en especulaciones humanas, sino en la palabra del Señor resucitado, quien aseguró que reuniría a los suyos.", references: "Juan 14:1-3; Hechos 1:9-11"),
      StudySection(title: "2. La enseñanza de Jesús", content: "En los Evangelios, Jesús habló de su venida y llamó a sus discípulos a vivir preparados. Sus enseñanzas buscan formar fidelidad, vigilancia y confianza, no curiosidad desordenada.", references: "Mateo 24:30-44; Lucas 21:25-28"),
      StudySection(title: "3. La confirmación apostólica", content: "Los apóstoles anunciaron el retorno de Cristo como parte de la esperanza de la Iglesia. La doctrina pertenece al testimonio del Nuevo Testamento y no a una tradición aislada.", references: "1 Tesalonicenses 4:13-18; Tito 2:11-13"),
      StudySection(title: "4. El mismo Jesús que ascendió", content: "Los mensajeros declararon que Jesús vendría de la misma manera en que fue visto ascender. El que regresará es el mismo Hijo encarnado, crucificado, resucitado y exaltado.", references: "Hechos 1:9-11"),
      StudySection(title: "5. Un acontecimiento futuro y real", content: "La segunda venida no es solamente una metáfora de la influencia de Jesús ni una descripción de su presencia espiritual en los creyentes. La Escritura la presenta como una intervención futura del Señor.", references: "Hechos 1:11; Apocalipsis 1:7"),
      StudySection(title: "6. La venida será manifiesta", content: "El Nuevo Testamento presenta el regreso de Cristo como un acontecimiento reconocible y glorioso. No debe confundirse con apariciones secretas atribuidas a supuestos salvadores o líderes humanos.", references: "Mateo 24:23-27; Apocalipsis 1:7"),
      StudySection(title: "7. La gloria del Hijo", content: "Cristo volverá en gloria y majestad. Su humillación durante la primera venida no significa falta de autoridad; el Padre le ha dado honra y autoridad universal.", references: "Mateo 25:31; Filipenses 2:9-11"),
      StudySection(title: "8. El Padre conoce el tiempo", content: "Jesús enseñó que el día y la hora no han sido revelados a los seres humanos. La autoridad sobre los tiempos pertenece a Dios, por lo que fijar fechas contradice la enseñanza de Cristo.", references: "Mateo 24:36; Hechos 1:7"),
      StudySection(title: "9. No calcular fechas", content: "Las señales y exhortaciones bíblicas no autorizan establecer calendarios exactos. Los intentos de anunciar fechas han desviado la atención de la obediencia y han producido falsas expectativas.", references: "Mateo 24:36,42; Marcos 13:32-33"),
      StudySection(title: "10. La vigilancia cristiana", content: "Velar significa vivir atentos a la voluntad de Dios, perseverar en la fe y no permitir que la indiferencia espiritual domine. No significa vivir aterrorizados ni abandonar las responsabilidades cotidianas.", references: "Mateo 24:42-44; Lucas 21:34-36"),
      StudySection(title: "11. La parábola de las diez vírgenes", content: "Jesús utilizó la parábola para enseñar la necesidad de estar preparados. La demora aparente no debe conducir al descuido, porque la responsabilidad espiritual no puede delegarse en otros.", references: "Mateo 25:1-13"),
      StudySection(title: "12. El siervo fiel y prudente", content: "La espera del Señor debe reflejarse en fidelidad a las responsabilidades recibidas. Jesús contrapone al siervo responsable con quien utiliza la demora como excusa para actuar injustamente.", references: "Mateo 24:45-51"),
      StudySection(title: "13. Los talentos y la responsabilidad", content: "La parábola de los talentos enseña que los siervos deben administrar fielmente lo que recibieron. La esperanza futura impulsa servicio responsable, no pasividad.", references: "Mateo 25:14-30"),
      StudySection(title: "14. El juicio de las naciones", content: "La enseñanza de Mateo 25 relaciona la venida gloriosa del Hijo del Hombre con su autoridad para juzgar. La fe debe expresarse en misericordia y atención al prójimo.", references: "Mateo 25:31-46"),
      StudySection(title: "15. Consuelo para los creyentes", content: "Pablo presentó la venida del Señor como consuelo para creyentes que enfrentaban la muerte y la separación. La esperanza futura sostiene a la comunidad en el duelo y la perseverancia.", references: "1 Tesalonicenses 4:13-18"),
      StudySection(title: "16. Los que murieron en Cristo", content: "La esperanza cristiana incluye a quienes murieron perteneciendo a Cristo. Pablo enseña que Dios no los olvida y que participarán de la consumación que acompaña el regreso del Señor.", references: "1 Tesalonicenses 4:14-16"),
      StudySection(title: "17. La resurrección de los creyentes", content: "En relación con la venida de Cristo, los muertos en él resucitarán. Este acontecimiento debe distinguirse de la resurrección histórica de Jesús, que es su fundamento y garantía.", references: "1 Corintios 15:20-23,51-54; 1 Tesalonicenses 4:16"),
      StudySection(title: "18. La transformación de los creyentes vivos", content: "Pablo enseña que los creyentes que estén vivos serán transformados. La esperanza no depende de escapar de la condición humana por esfuerzo propio, sino del poder de Dios.", references: "1 Corintios 15:51-53; 1 Tesalonicenses 4:17"),
      StudySection(title: "19. El encuentro con el Señor", content: "La Iglesia será reunida con Cristo. El centro de esta esperanza no es satisfacer curiosidad sobre detalles, sino estar para siempre con el Señor.", references: "1 Tesalonicenses 4:17-18"),
      StudySection(title: "20. La esperanza de la reunión", content: "La venida de Cristo significa que la separación y la muerte no tendrán la última palabra sobre quienes le pertenecen. La comunión definitiva con el Señor sostiene la esperanza cristiana.", references: "Juan 14:3; 1 Tesalonicenses 4:17"),
      StudySection(title: "21. La manifestación de Cristo y la vida nueva", content: "Cuando Cristo se manifieste, los creyentes serán manifestados con él en gloria. Esta esperanza impulsa a vivir ahora de acuerdo con la identidad recibida en el Hijo.", references: "Colosenses 3:1-4; 1 Juan 3:2-3"),
      StudySection(title: "22. La purificación de la esperanza", content: "Juan relaciona la esperanza de ver a Cristo con la purificación de la vida. Esperar su venida no es una excusa para descuidar la santidad, sino un llamado a vivir en ella.", references: "1 Juan 3:2-3; 2 Pedro 3:11-14"),
      StudySection(title: "23. La gracia que enseña a esperar", content: "La gracia de Dios educa al creyente para renunciar a la impiedad y vivir sobriamente mientras espera la manifestación gloriosa de Jesucristo.", references: "Tito 2:11-14"),
      StudySection(title: "24. La perseverancia bajo presión", content: "La esperanza del regreso de Cristo fortalece a los creyentes que atraviesan dificultades. La perseverancia no nace de negar el sufrimiento, sino de confiar en la fidelidad del Señor.", references: "Santiago 5:7-8; 1 Pedro 1:6-9"),
      StudySection(title: "25. La paciencia del Señor", content: "La aparente demora no significa que Dios haya olvidado su promesa. Pedro enseña que la paciencia divina ofrece oportunidad para el arrepentimiento y debe ser comprendida con reverencia.", references: "2 Pedro 3:8-9,15"),
      StudySection(title: "26. Rechazar las burlas", content: "La Escritura advierte que algunos se burlarán de la promesa del regreso de Cristo. La Iglesia debe responder con fidelidad bíblica y no con disputas orgullosas o afirmaciones sin fundamento.", references: "2 Pedro 3:3-7"),
      StudySection(title: "27. La venida no es motivo de especulación", content: "Los pasajes proféticos deben interpretarse con cuidado, respetando su contexto y propósito. La doctrina no debe convertirse en fuente de rumores, cálculos o sensacionalismo.", references: "Mateo 24:4-5,23-27; 2 Tesalonicenses 2:1-3"),
      StudySection(title: "28. Advertencia contra los falsos cristos", content: "Jesús advirtió que surgirían personas que afirmarían ser el Cristo o anunciarían su presencia en lugares ocultos. La Iglesia debe permanecer fiel al testimonio bíblico.", references: "Mateo 24:23-26"),
      StudySection(title: "29. La apostasía y el engaño", content: "Pablo advirtió sobre el engaño y la rebelión antes del día del Señor. Estos pasajes requieren interpretación responsable y no deben usarse para identificar arbitrariamente a personas o acontecimientos actuales.", references: "2 Tesalonicenses 2:1-3"),
      StudySection(title: "30. La revelación del hombre de pecado", content: "Segunda de Tesalonicenses presenta una figura de oposición y engaño cuya manifestación está bajo el límite soberano de Dios. El pasaje llama a permanecer firmes en la verdad apostólica.", references: "2 Tesalonicenses 2:3-10"),
      StudySection(title: "31. El anticristo y el discernimiento", content: "Las cartas de Juan advierten sobre el espíritu del anticristo y los falsos maestros. La Iglesia debe discernir por su confesión acerca de Jesucristo y su fidelidad al evangelio.", references: "1 Juan 2:18-23; 4:1-3"),
      StudySection(title: "32. La esperanza no es temor constante", content: "La enseñanza sobre la venida de Cristo busca consolar, fortalecer y llamar a la fidelidad. No debe utilizarse para manipular a las personas mediante pánico o amenazas humanas.", references: "1 Tesalonicenses 4:18; 5:9-11"),
      StudySection(title: "33. La sobriedad y la vigilancia", content: "Pablo exhorta a vivir despiertos y sobrios, revestidos de fe, amor y esperanza. La preparación cristiana es una forma de vida sostenida por la gracia.", references: "1 Tesalonicenses 5:1-8"),
      StudySection(title: "34. La vida cotidiana mientras esperamos", content: "Esperar al Señor incluye trabajar responsablemente, hacer el bien y cumplir las tareas ordinarias. La expectativa futura no justifica abandonar las obligaciones presentes.", references: "1 Tesalonicenses 4:9-12; 2 Tesalonicenses 3:6-13"),
      StudySection(title: "35. La santidad en comunidad", content: "La esperanza de la venida debe fortalecer el amor fraternal, la paz y la edificación mutua. La preparación no es individualismo, sino fidelidad compartida en la Iglesia.", references: "1 Tesalonicenses 5:11-15,23"),
      StudySection(title: "36. La fidelidad doctrinal", content: "La Iglesia debe conservar la enseñanza recibida y no dejarse mover fácilmente por mensajes que atribuyan falsamente autoridad apostólica a sus afirmaciones.", references: "2 Tesalonicenses 2:1-2,15; 2 Timoteo 1:13-14"),
      StudySection(title: "37. La venida y la justicia de Dios", content: "El regreso de Cristo manifiesta la justicia divina frente a la maldad y consuela a quienes sufren injustamente. La respuesta cristiana no es la venganza personal, sino confiar en el Juez justo.", references: "2 Tesalonicenses 1:5-10; Romanos 12:19"),
      StudySection(title: "38. La manifestación del reino de Cristo", content: "La venida de Jesús está relacionada con la manifestación plena de su autoridad. Su reino no depende de la fuerza política ni de la ambición humana, sino del propósito de Dios.", references: "1 Corintios 15:24-28; Apocalipsis 11:15"),
      StudySection(title: "39. La derrota definitiva de la muerte", content: "La esperanza futura incluye la derrota final de la muerte y de todo poder contrario al gobierno de Dios. Esta consumación se fundamenta en la victoria de Cristo resucitado.", references: "1 Corintios 15:25-26,54-57"),
      StudySection(title: "40. La creación espera su liberación", content: "La esperanza bíblica no se limita al destino individual: la creación misma espera ser liberada de la corrupción. La venida de Cristo pertenece a la consumación del propósito redentor de Dios.", references: "Romanos 8:18-23; 2 Pedro 3:13"),
      StudySection(title: "41. La nueva creación", content: "Pedro y Apocalipsis orientan la esperanza hacia cielos nuevos y tierra nueva donde habita la justicia. La expectativa futura llama a vivir hoy en santidad y fidelidad.", references: "2 Pedro 3:13; Apocalipsis 21:1-5"),
      StudySection(title: "42. El juicio y la responsabilidad humana", content: "La venida del Señor está vinculada al juicio justo. Cada persona es responsable delante de Dios, y esta verdad llama al arrepentimiento, a la fe y a una vida íntegra.", references: "Mateo 25:31-46; 2 Corintios 5:10"),
      StudySection(title: "43. La recompensa y la fidelidad", content: "El Nuevo Testamento habla de la recompensa del Señor para quienes le sirven. Esta esperanza no convierte las obras en precio de salvación, sino que reconoce la fidelidad de Dios hacia sus siervos.", references: "2 Timoteo 4:7-8; Apocalipsis 22:12"),
      StudySection(title: "44. La oración por la venida del Señor", content: "La Iglesia expresa su esperanza pidiendo que el Señor venga. Esta oración manifiesta amor por Cristo y deseo de que el propósito de Dios llegue a su plenitud.", references: "Apocalipsis 22:20; 1 Corintios 16:22"),
      StudySection(title: "45. El Espíritu y la esperanza de la Iglesia", content: "El Espíritu Santo fortalece a los creyentes y los orienta hacia Cristo. La esperanza de la venida se vive en dependencia del Espíritu, quien produce perseverancia y fidelidad.", references: "Romanos 8:23-25; Gálatas 5:5"),
      StudySection(title: "46. La perspectiva trinitaria de la consumación", content: "El Padre ha establecido su propósito, el Hijo volverá con gloria y el Espíritu sostiene a la Iglesia en la esperanza. Las personas divinas no son tres salvadores ni tres planes separados, sino el único Dios obrando conforme a su voluntad.", references: "Mateo 24:36; Juan 14:16-18; Tito 2:13-14"),
      StudySection(title: "47. La Iglesia anuncia la esperanza", content: "La comunidad cristiana proclama la muerte y resurrección de Cristo y espera su regreso. Su testimonio debe unir verdad, amor, servicio y perseverancia.", references: "1 Corintios 11:26; Mateo 28:18-20"),
      StudySection(title: "48. Consolar sin fijar fechas", content: "La enseñanza profética debe comunicarse para edificación y consuelo. Los responsables deben evitar pronósticos, amenazas y calendarios que la Escritura no revela.", references: "1 Tesalonicenses 4:18; 5:11; Hechos 1:7"),
      StudySection(title: "49. La preparación es fidelidad presente", content: "Estar preparados significa permanecer en Cristo, obedecer su Palabra, amar al prójimo y servir con constancia. No consiste en abandonar la vida diaria ni en buscar señales a cada momento.", references: "Mateo 24:45-46; Juan 15:4-10"),
      StudySection(title: "50. La certeza de la promesa", content: "La esperanza descansa en la fidelidad de Jesucristo. Quien prometió volver es digno de confianza, por lo que la Iglesia puede esperar con paciencia, fe y firmeza.", references: "Hebreos 10:23,35-37; Apocalipsis 22:20"),
    ],
    conclusion: "La segunda venida de Jesucristo es una promesa segura que llama a la Iglesia a vivir con esperanza, vigilancia y fidelidad. El Señor volverá conforme a la voluntad del Padre, reunirá a los que le pertenecen, manifestará su justicia y llevará a plenitud el propósito redentor de Dios. La Escritura no revela una fecha que los seres humanos puedan calcular, por lo que toda predicción debe rechazarse. La espera cristiana tampoco es pasividad ni temor permanente: se expresa en santidad, amor, servicio, perseverancia y consuelo mutuo. La resurrección de los creyentes y la derrota final de la muerte muestran que la esperanza descansa en la victoria de Cristo. El Espíritu fortalece a la Iglesia mientras espera, y el Padre cumplirá fielmente su propósito por medio del Hijo. Por eso, la respuesta apropiada de la Iglesia es permanecer firme en la Palabra y vivir de tal manera que pueda decir con confianza: ven, Señor Jesús.",
  ),
Study(
    number: '78',
    title: "La persecución de la Iglesia: sufrimiento, fidelidad y testimonio cristiano en medio de la oposición",
    subtitle: "Un estudio bíblico sobre la oposición contra los creyentes, la respuesta de la Iglesia y la fidelidad del Dios trino en medio del sufrimiento.",
    introduction: "La persecución de la Iglesia es una realidad que aparece desde los primeros relatos bíblicos hasta las enseñanzas de Jesús y los escritos apostólicos. El Señor advirtió que sus discípulos podrían enfrentar rechazo por causa de su nombre, y el libro de Hechos registra cómo la Iglesia respondió mediante oración, valentía, servicio y proclamación del evangelio. Este estudio examina las causas y formas de la oposición, la diferencia entre sufrir por hacer el bien y afrontar consecuencias de conductas incorrectas, y la manera bíblica de responder sin venganza ni violencia. También considera la responsabilidad de la comunidad cristiana de acompañar a quienes padecen injusticia, proteger a los vulnerables y mantener un testimonio íntegro. Desde la perspectiva trinitaria, el Padre consuela, Jesucristo es el ejemplo y Señor de la Iglesia, y el Espíritu Santo fortalece a los creyentes para testificar. La finalidad no es glorificar el sufrimiento, sino aprender a permanecer fieles a Cristo con verdad, prudencia, amor y esperanza.",
    sections: [
      StudySection(title: "1. La realidad de la persecución", content: "Jesús advirtió que sus discípulos enfrentarían oposición por causa de su nombre. La persecución puede adoptar distintas formas y debe comprenderse a la luz del testimonio bíblico.", references: "Juan 15:18-20; 2 Timoteo 3:12"),
      StudySection(title: "2. La causa de la oposición", content: "La oposición surge cuando la fidelidad a Cristo confronta valores, prácticas o autoridades contrarias al evangelio. No todo desacuerdo es persecución; es necesario discernir con honestidad.", references: "Juan 3:19-21; 1 Pedro 4:15-16"),
      StudySection(title: "3. Jesús, el perseguido y fiel", content: "Jesucristo sufrió rechazo e injusticia sin abandonar su misión. Su vida ofrece el modelo supremo de fidelidad, verdad y obediencia al Padre.", references: "Isaías 53:3; Hebreos 12:2-3"),
      StudySection(title: "4. El anuncio de Jesús a sus discípulos", content: "Jesús no prometió una vida sin dificultades. Preparó a sus seguidores para responder con confianza, prudencia y perseverancia cuando fueran rechazados.", references: "Mateo 10:16-23; Juan 16:1-4"),
      StudySection(title: "5. La persecución en el libro de Hechos", content: "Hechos muestra que la oposición no detuvo la proclamación apostólica. La Iglesia respondió con oración, valentía y dependencia del Espíritu Santo.", references: "Hechos 4:18-31; 5:40-42"),
      StudySection(title: "6. La valentía de los apóstoles", content: "Pedro y Juan afirmaron que debían obedecer a Dios antes que a los hombres. Su respuesta muestra que la fidelidad a Dios tiene prioridad ante órdenes injustas que exigen desobediencia.", references: "Hechos 4:18-20; 5:27-29"),
      StudySection(title: "7. Esteban y el testimonio hasta el final", content: "Esteban mantuvo su testimonio acerca de Cristo ante una oposición violenta. Su relato muestra la importancia de la verdad, el valor y la confianza en Dios.", references: "Hechos 6:8-15; 7:54-60"),
      StudySection(title: "8. La conversión de Saulo", content: "Saulo participó en la persecución de la Iglesia, pero Cristo lo confrontó y transformó. Su historia demuestra que Dios puede cambiar a quien antes se oponía al evangelio.", references: "Hechos 8:1-3; 9:1-22"),
      StudySection(title: "9. La Iglesia dispersada y la misión", content: "La dispersión de los creyentes llevó el mensaje a otros lugares. Dios puede obrar aun en circunstancias adversas, sin que eso signifique que la injusticia sea buena.", references: "Hechos 8:1-8; 11:19-21"),
      StudySection(title: "10. La oración de la Iglesia perseguida", content: "Ante las amenazas, los creyentes oraron pidiendo valentía para anunciar la Palabra. No se concentraron únicamente en pedir que desapareciera la dificultad.", references: "Hechos 4:23-31"),
      StudySection(title: "11. El poder del Espíritu Santo", content: "El Espíritu capacita a los creyentes para dar testimonio de Cristo con valor y sabiduría. La valentía cristiana no depende solo de fuerza de carácter.", references: "Hechos 1:8; 4:31"),
      StudySection(title: "12. La persecución y la identidad cristiana", content: "La oposición no define el valor del creyente. Su identidad descansa en Cristo y en la gracia de Dios, no en la aceptación de la sociedad.", references: "1 Pedro 2:9-12; Romanos 8:15-17"),
      StudySection(title: "13. Sufrir por hacer el bien", content: "Pedro distingue el sufrimiento por hacer el bien del sufrimiento causado por conductas injustas. El cristiano debe examinar su conducta y no atribuir automáticamente toda consecuencia a persecución.", references: "1 Pedro 3:14-17; 4:15-16"),
      StudySection(title: "14. La diferencia entre persecución y consecuencias personales", content: "No toda crítica, conflicto o sanción constituye persecución religiosa. La Escritura llama a vivir con integridad y asumir las consecuencias de acciones incorrectas.", references: "1 Pedro 2:19-20; 4:15"),
      StudySection(title: "15. La respuesta sin venganza", content: "El creyente no debe responder al mal con mal ni buscar venganza personal. Está llamado a confiar en la justicia de Dios y actuar con rectitud.", references: "Romanos 12:17-21; 1 Pedro 2:21-23"),
      StudySection(title: "16. Amar a los enemigos", content: "Jesús ordenó amar y orar por quienes persiguen. Este mandato no aprueba la injusticia, sino que impide que el odio gobierne el corazón del discípulo.", references: "Mateo 5:43-48; Lucas 6:27-28"),
      StudySection(title: "17. Bendecir y no maldecir", content: "La enseñanza apostólica llama a bendecir a quienes persiguen y evitar palabras de odio. La respuesta cristiana debe reflejar el carácter de Cristo.", references: "Romanos 12:14; 1 Corintios 4:12-13"),
      StudySection(title: "18. La mansedumbre al defender la fe", content: "El creyente debe estar preparado para explicar su esperanza con mansedumbre y respeto. La defensa de la fe no autoriza insultos ni arrogancia.", references: "1 Pedro 3:15-16; 2 Timoteo 2:24-25"),
      StudySection(title: "19. La prudencia ante el peligro", content: "Jesús enseñó a combinar la sencillez con la prudencia. Buscar seguridad, evitar riesgos innecesarios y actuar con sabiduría no equivale a negar la fe.", references: "Mateo 10:16,23; Proverbios 22:3"),
      StudySection(title: "20. La obediencia a Dios y los límites de la autoridad", content: "Las autoridades cumplen funciones legítimas, pero ninguna autoridad humana debe ocupar el lugar de Dios. Cuando se exige desobedecer claramente al Señor, los creyentes deben mantener su fidelidad con responsabilidad.", references: "Hechos 5:29; Romanos 13:1-7"),
      StudySection(title: "21. La libertad de conciencia", content: "La fe no debe imponerse mediante violencia o coerción. La convicción cristiana se comunica con verdad y respeto, reconociendo la responsabilidad personal delante de Dios.", references: "Romanos 14:4,12; 2 Corintios 4:2"),
      StudySection(title: "22. La perseverancia en la prueba", content: "La Escritura llama a permanecer firmes cuando llega la oposición. La perseverancia no significa negar el dolor, sino continuar confiando en Dios.", references: "Santiago 1:2-4; Romanos 5:3-5"),
      StudySection(title: "23. El consuelo de Dios", content: "Dios es presentado como Padre de misericordias y Dios de toda consolación. Su consuelo sostiene a quienes atraviesan aflicción y también los capacita para acompañar a otros.", references: "2 Corintios 1:3-7"),
      StudySection(title: "24. La presencia de Cristo en el sufrimiento", content: "Jesús prometió estar con sus discípulos y no abandonarlos. La presencia del Señor sostiene la fe aun cuando las circunstancias no cambian de inmediato.", references: "Mateo 28:20; Juan 14:18"),
      StudySection(title: "25. La esperanza que no avergüenza", content: "La esperanza cristiana se fundamenta en el amor de Dios derramado por el Espíritu Santo. La oposición presente no anula las promesas divinas.", references: "Romanos 5:1-5; 8:18"),
      StudySection(title: "26. La perspectiva eterna", content: "Pablo enseña a mirar más allá de las aflicciones temporales hacia la gloria eterna. Esto no minimiza el sufrimiento, sino que sitúa la esperanza en la fidelidad de Dios.", references: "2 Corintios 4:16-18"),
      StudySection(title: "27. La comunión de los creyentes", content: "La Iglesia debe acompañar a quienes sufren, orar por ellos y atender sus necesidades concretas. La persecución no debe enfrentarse en aislamiento.", references: "1 Corintios 12:25-26; Hebreos 13:3"),
      StudySection(title: "28. Compartir las cargas", content: "Los creyentes son llamados a llevar las cargas unos de otros. El apoyo puede incluir oración, ayuda material, acompañamiento y defensa responsable de quienes padecen injusticia.", references: "Gálatas 6:2; Romanos 12:13"),
      StudySection(title: "29. La responsabilidad de los pastores", content: "Quienes dirigen la Iglesia deben cuidar al rebaño, proteger a los vulnerables y no utilizar el sufrimiento ajeno para controlar o manipular.", references: "1 Pedro 5:1-4; Hechos 20:28"),
      StudySection(title: "30. No abandonar a quienes sufren", content: "La comunidad cristiana no debe olvidar a quienes enfrentan prisión, rechazo o necesidad por su fe. La solidaridad es una expresión concreta del amor cristiano.", references: "Hebreos 10:32-34; 13:3"),
      StudySection(title: "31. El testimonio público de la Iglesia", content: "La conducta de los creyentes puede dar testimonio incluso ante quienes no comparten su fe. La integridad y las buenas obras deben acompañar la proclamación.", references: "Mateo 5:14-16; 1 Pedro 2:12"),
      StudySection(title: "32. La proclamación del evangelio sin violencia", content: "El evangelio se anuncia mediante la verdad, el amor y la persuasión, nunca mediante coacción o agresión. El poder de la misión procede de Dios.", references: "2 Corintios 4:1-2; 5:20"),
      StudySection(title: "33. La fidelidad frente a la presión social", content: "La aprobación de las personas no debe convertirse en el criterio supremo del creyente. La fidelidad a Cristo requiere discernir y mantener convicciones bíblicas.", references: "Gálatas 1:10; Romanos 12:2"),
      StudySection(title: "34. El peligro del temor humano", content: "El temor a la opinión de otros puede llevar a ocultar convicciones o actuar contra la conciencia. La Escritura llama a confiar en Dios por encima de la aprobación humana.", references: "Proverbios 29:25; Mateo 10:28"),
      StudySection(title: "35. La negación de Cristo y la restauración", content: "Los relatos de Pedro muestran que una caída no tiene que ser el final de la historia. Cristo puede restaurar al arrepentido y llamarlo nuevamente al servicio.", references: "Lucas 22:54-62; Juan 21:15-19"),
      StudySection(title: "36. La fidelidad de Pablo en las aflicciones", content: "Pablo describe dificultades y oposición mientras cumple su misión. Su ejemplo destaca la dependencia de Cristo y la centralidad del evangelio.", references: "2 Corintios 11:23-28; 2 Timoteo 4:6-8"),
      StudySection(title: "37. La iglesia de Tesalónica", content: "Los creyentes de Tesalónica recibieron la Palabra en medio de aflicción y llegaron a ser ejemplo para otros. Su fe se manifestó en perseverancia y esperanza.", references: "1 Tesalonicenses 1:6-8; 2:14"),
      StudySection(title: "38. Las iglesias de Asia y el llamado a vencer", content: "Los mensajes de Apocalipsis reconocen las dificultades de las iglesias y las llaman a permanecer fieles. La victoria se relaciona con la fidelidad a Cristo.", references: "Apocalipsis 2:8-11; 3:10-12"),
      StudySection(title: "39. La promesa de recompensa", content: "Jesús anima a quienes sufren por causa de la justicia con la promesa del reino. La recompensa no convierte el sufrimiento en algo deseable por sí mismo, sino que afirma la justicia y fidelidad de Dios.", references: "Mateo 5:10-12; Lucas 6:22-23"),
      StudySection(title: "40. La sangre de los mártires y la justicia divina", content: "Apocalipsis presenta a los testigos fieles clamando por justicia. El texto afirma que Dios conoce el sufrimiento y no permitirá que la injusticia tenga la última palabra.", references: "Apocalipsis 6:9-11"),
      StudySection(title: "41. La verdad frente a la propaganda y el engaño", content: "En contextos hostiles pueden difundirse acusaciones falsas. El creyente debe evitar la mentira, verificar la información y responder con verdad y dominio propio.", references: "Éxodo 20:16; Efesios 4:25; 1 Pedro 2:12"),
      StudySection(title: "42. La unidad en medio de la oposición", content: "La presión externa no debe convertirse en motivo de divisiones internas. La Iglesia está llamada a conservar la unidad en Cristo y a tratar sus diferencias con humildad.", references: "Efesios 4:1-6; Filipenses 1:27-28"),
      StudySection(title: "43. La misión continúa en circunstancias difíciles", content: "La oposición no cancela el llamado a hacer discípulos. La Iglesia debe buscar formas responsables y pacíficas de continuar enseñando y sirviendo.", references: "Mateo 28:19-20; Hechos 5:42"),
      StudySection(title: "44. El discernimiento ante falsas acusaciones", content: "Los cristianos deben distinguir entre una acusación verdadera, una crítica legítima y una calumnia. La humildad permite corregir errores propios y rechazar injusticias sin arrogancia.", references: "Proverbios 18:17; 1 Pedro 3:16"),
      StudySection(title: "45. La protección de los vulnerables", content: "La comunidad debe prestar especial atención a niños, familias y personas expuestas a amenazas. La fe bíblica exige justicia, compasión y protección del débil.", references: "Salmo 82:3-4; Proverbios 31:8-9"),
      StudySection(title: "46. La paz como testimonio", content: "En cuanto dependa del creyente, debe procurar la paz con todos. La paz no exige renunciar a la verdad, sino rechazar la hostilidad y buscar el bien.", references: "Romanos 12:18; Hebreos 12:14"),
      StudySection(title: "47. El Padre sostiene a sus hijos", content: "La Escritura presenta al Padre como fuente de consuelo y fortaleza. Su cuidado no significa ausencia de pruebas, sino fidelidad durante ellas.", references: "2 Corintios 1:3-4; 1 Pedro 1:3-5"),
      StudySection(title: "48. El Hijo es el ejemplo y Señor de la Iglesia", content: "Jesucristo sufrió injustamente, venció mediante la obediencia y es el Señor a quien la Iglesia confiesa. Seguirlo implica imitar su fidelidad y depender de su gracia.", references: "1 Pedro 2:21-24; Hebreos 12:2-3"),
      StudySection(title: "49. El Espíritu Santo fortalece el testimonio", content: "El Espíritu Santo capacita para dar testimonio de Cristo y produce amor, dominio propio y valentía. Su obra no promueve violencia ni orgullo.", references: "Hechos 1:8; 2 Timoteo 1:7-8"),
      StudySection(title: "50. La Trinidad y la esperanza de la Iglesia perseguida", content: "El Padre consuela, el Hijo acompaña y gobierna a su Iglesia, y el Espíritu la fortalece para testificar. La esperanza cristiana descansa en la fidelidad del Dios trino.", references: "2 Corintios 1:3-4; Mateo 28:20; Juan 15:26; Hechos 1:8"),
    ],
    conclusion: "La Escritura enseña que la Iglesia puede enfrentar oposición por causa de su fidelidad a Jesucristo, pero también establece cómo debe responder: con verdad, mansedumbre, prudencia, oración, amor a los enemigos y perseverancia. No todo conflicto es persecución, y el creyente debe examinar su conducta antes de atribuir a la fe cualquier consecuencia. La comunidad cristiana tiene la responsabilidad de acompañar a quienes sufren, proteger a los vulnerables y continuar anunciando el evangelio sin violencia ni coerción. El sufrimiento no debe buscarse ni romantizarse; cuando llega, la esperanza descansa en la presencia y fidelidad de Dios. El Padre consuela a sus hijos, el Hijo gobierna y acompaña a su Iglesia, y el Espíritu Santo fortalece su testimonio. Así, aun en circunstancias difíciles, la Iglesia está llamada a reflejar el carácter de Cristo y a permanecer firme en la verdad.",
  ),
Study(
    number: '79',
    title: "Satanás y los demonios: identidad, límites, oposición y victoria de Cristo",
    subtitle: "Un examen bíblico de la realidad del adversario, la actividad de los espíritus malignos, los límites de su poder y la victoria definitiva de Jesucristo.",
    introduction: "La Biblia enseña que existe una oposición espiritual real contra Dios y contra su obra, pero nunca presenta a Satanás como un poder igual al Creador. El adversario es una criatura, tiene límites y está sujeto al juicio divino. Los Evangelios muestran la autoridad de Jesucristo sobre los espíritus malignos y los escritos apostólicos explican que, mediante su muerte y resurrección, Cristo venció el poder del pecado y de la muerte. Este estudio examina la identidad y actividad de Satanás y los demonios, distingue las afirmaciones bíblicas de las especulaciones, y presenta la respuesta que corresponde a la Iglesia: verdad, oración, fe, sobriedad, santidad, amor y confianza en el Señor. También advierte contra el sensacionalismo, la manipulación del miedo y la atribución automática de enfermedades o dificultades a causas demoníacas. Desde la perspectiva trinitaria, el Padre lleva adelante su propósito soberano, el Hijo ha triunfado sobre los poderes del mal y el Espíritu Santo fortalece al creyente para vivir en fidelidad. La atención central no debe estar en el adversario, sino en Jesucristo, cuya autoridad y victoria son definitivas.",
    sections: [
      StudySection(title: "1. La existencia de Satanás en el testimonio bíblico", content: "La Biblia presenta a Satanás como un adversario real, no como una fuerza equivalente a Dios. Su existencia debe afirmarse dentro de los límites de lo que la revelación enseña, sin añadir mitos ni especulaciones.", references: "Job 1:6-12; Zacarías 3:1-2; Mateo 4:1-11; Apocalipsis 12:9"),
      StudySection(title: "2. El significado de los nombres y títulos del adversario", content: "Los títulos Satanás, diablo, tentador, maligno y acusador describen aspectos de su oposición. Cada nombre ilumina su actividad, pero ninguno indica que posea atributos divinos.", references: "Mateo 4:3; Juan 8:44; Efesios 6:11; Apocalipsis 12:10"),
      StudySection(title: "3. Satanás es una criatura, no un segundo dios", content: "La fe bíblica es monoteísta: solo el Señor es Dios eterno y todopoderoso. Satanás pertenece al orden creado y depende de los límites que Dios establece.", references: "Deuteronomio 6:4; Nehemías 9:6; Colosenses 1:16-17; Job 1:12"),
      StudySection(title: "4. La rebelión y caída del diablo: lo que la Biblia afirma y lo que no especifica", content: "Algunos pasajes se han relacionado tradicionalmente con la caída de Satanás, pero deben leerse en su contexto histórico y literario. La Escritura afirma su maldad y oposición, aunque no ofrece una narración completa de todos los detalles de su origen.", references: "Isaías 14:4-15; Ezequiel 28:1-19; Juan 8:44; 1 Timoteo 3:6"),
      StudySection(title: "5. El orgullo como raíz de la oposición a Dios", content: "La arrogancia aparece asociada con la caída y con la conducta del adversario. El orgullo busca exaltarse y rechaza la dependencia del Creador; por eso la humildad es una virtud esencial del creyente.", references: "1 Timoteo 3:6; Proverbios 16:18; Santiago 4:6-7"),
      StudySection(title: "6. El diablo como mentiroso y padre de mentira", content: "Jesús identifica la mentira como característica del diablo. La falsedad distorsiona el carácter de Dios, confunde la conciencia y conduce a decisiones contrarias a la verdad.", references: "Juan 8:44; Génesis 3:1-5; 2 Corintios 11:3"),
      StudySection(title: "7. El adversario como tentador", content: "La tentación busca inducir al ser humano a desconfiar de Dios y desobedecer su Palabra. La responsabilidad moral de cada persona no desaparece por la existencia de tentaciones externas.", references: "Mateo 4:1-11; 1 Tesalonicenses 3:5; Santiago 1:13-15"),
      StudySection(title: "8. El acusador y la condenación", content: "La Biblia describe al diablo como acusador, pero enseña que la justificación y la intercesión de Cristo son fundamento de la seguridad del creyente. La acusación no tiene autoridad para anular la obra redentora de Dios.", references: "Zacarías 3:1-5; Apocalipsis 12:10-11; Romanos 8:1, 33-34"),
      StudySection(title: "9. El engaño religioso y la apariencia de verdad", content: "La oposición espiritual puede presentarse con apariencia de piedad o de verdad. Por ello, la Iglesia debe examinar las enseñanzas y no aceptar una afirmación solo por su apariencia, popularidad o lenguaje religioso.", references: "2 Corintios 11:13-15; Mateo 7:15-20; 1 Juan 4:1"),
      StudySection(title: "10. La actividad de Satanás en el libro de Job", content: "Job muestra que el adversario actúa bajo límites y no posee autoridad independiente sobre la creación. El relato no explica cada sufrimiento humano como ataque demoníaco, sino que llama a evitar conclusiones precipitadas.", references: "Job 1:6-22; Job 2:1-10; Job 42:1-6"),
      StudySection(title: "11. La serpiente y el engaño en Génesis", content: "Génesis 3 narra la entrada del engaño y la desobediencia en la experiencia humana. La identificación de la serpiente con Satanás aparece explícitamente en textos posteriores y debe entenderse desde el testimonio bíblico completo.", references: "Génesis 3:1-15; Apocalipsis 12:9; 20:2"),
      StudySection(title: "12. La oposición del diablo al ministerio de Jesús", content: "Los Evangelios presentan a Satanás intentando desviar a Jesús de su misión. Cristo responde con obediencia al Padre y fidelidad a las Escrituras, sin ceder a propuestas que contradicen la voluntad divina.", references: "Mateo 4:1-11; Marcos 1:12-13; Lucas 4:1-13"),
      StudySection(title: "13. La tentación de Jesús y su victoria obediente", content: "Jesús fue tentado, pero no pecó. Su victoria muestra su fidelidad perfecta y no debe confundirse con la idea de que el mal tuviera dominio moral sobre Él.", references: "Hebreos 4:15; Mateo 4:1-11; 1 Pedro 2:22"),
      StudySection(title: "14. Los demonios en la enseñanza de los Evangelios", content: "Los Evangelios registran la actividad de espíritus malignos y la autoridad de Jesús sobre ellos. Estos relatos deben leerse con seriedad, sin convertir cada enfermedad, dificultad o conducta humana en una supuesta manifestación demoníaca.", references: "Marcos 1:23-27; Lucas 8:26-39; Mateo 12:22-28"),
      StudySection(title: "15. La identidad de los demonios según el testimonio bíblico", content: "La Escritura presenta a los demonios como seres espirituales malignos que se oponen a Dios y perjudican a las personas. No deben confundirse con seres humanos fallecidos ni recibir atributos que pertenecen únicamente al Señor.", references: "Mateo 8:28-32; Marcos 5:1-13; Santiago 2:19"),
      StudySection(title: "16. La diferencia entre ángeles fieles y espíritus malignos", content: "Los ángeles fieles sirven a Dios, mientras que los espíritus malignos aparecen asociados con rebelión y oposición. La Biblia no invita a rendir culto a ninguno de ellos, sino a adorar exclusivamente al Creador.", references: "Salmos 103:20-21; Hebreos 1:14; Judas 6; Apocalipsis 22:8-9"),
      StudySection(title: "17. La limitación del conocimiento y poder demoníacos", content: "Los seres malignos no son omniscientes, omnipresentes ni omnipotentes. Esos atributos pertenecen a Dios. La Biblia advierte sobre su actividad, pero prohíbe convertirla en motivo de temor supersticioso.", references: "Job 1:12; Mateo 24:36; Salmos 139:1-12; 1 Juan 4:4"),
      StudySection(title: "18. La autoridad de Jesucristo sobre los demonios", content: "Jesús ordena a los espíritus malignos y estos se someten a su autoridad. Su poder no procede de prácticas mágicas, fórmulas o negociación con los espíritus, sino de su identidad y autoridad divinas.", references: "Marcos 1:27; Lucas 4:36; Lucas 11:20"),
      StudySection(title: "19. La liberación como señal del reino de Dios", content: "Las liberaciones realizadas por Jesús muestran que el reino de Dios confronta el dominio del mal. No son espectáculos ni herramientas de prestigio personal, sino manifestaciones de la autoridad misericordiosa de Cristo.", references: "Mateo 12:28-29; Lucas 11:20; Hechos 10:38"),
      StudySection(title: "20. La derrota del adversario en la cruz", content: "La muerte de Cristo no fue una victoria de Satanás, sino parte del propósito redentor de Dios. Por medio de su muerte, Jesús quebrantó el poder de aquel que tenía el imperio de la muerte y abrió el camino de la reconciliación.", references: "Colosenses 2:13-15; Hebreos 2:14-15; Juan 12:31-33"),
      StudySection(title: "21. La resurrección de Cristo y la derrota del poder de la muerte", content: "La resurrección confirma la victoria de Jesús y garantiza que la muerte no tendrá la última palabra. La esperanza cristiana descansa en el Cristo resucitado, no en el temor al adversario.", references: "1 Corintios 15:20-26, 54-57; Apocalipsis 1:17-18"),
      StudySection(title: "22. La exaltación de Cristo sobre todo poder", content: "El Hijo resucitado está exaltado sobre todo principado, autoridad y dominio. Ningún poder espiritual puede colocarse al mismo nivel que Jesucristo ni frustrar su señorío final.", references: "Efesios 1:20-23; Filipenses 2:9-11; Colosenses 2:10"),
      StudySection(title: "23. El testimonio apostólico sobre la derrota del diablo", content: "Los apóstoles anuncian que Cristo apareció para deshacer las obras del diablo y que el poder del maligno no puede separar al creyente del amor de Dios. La Iglesia vive desde la victoria de Cristo y espera su consumación.", references: "1 Juan 3:8; Romanos 8:35-39; Hebreos 2:14"),
      StudySection(title: "24. La armadura de Dios y la resistencia espiritual", content: "Efesios 6 describe la armadura de Dios mediante la verdad, la justicia, el evangelio de la paz, la fe, la salvación y la Palabra. La resistencia cristiana se fundamenta en Dios y no en objetos considerados mágicos.", references: "Efesios 6:10-18; 2 Corintios 10:3-5"),
      StudySection(title: "25. La verdad como defensa frente al engaño", content: "La verdad bíblica permite reconocer enseñanzas falsas y rechazar la mentira. El creyente debe formar su criterio mediante el estudio responsable de las Escrituras y la obediencia a Cristo.", references: "Juan 17:17; Efesios 4:14-15; 2 Timoteo 3:16-17"),
      StudySection(title: "26. La fe como escudo frente a los ataques", content: "La fe confía en el carácter y las promesas de Dios aun cuando aparecen dudas, presiones o acusaciones. No es pensamiento mágico ni garantía de ausencia de problemas, sino dependencia perseverante del Señor.", references: "Efesios 6:16; 1 Pedro 5:8-9; 1 Juan 5:4"),
      StudySection(title: "27. La oración y la dependencia de Dios", content: "La oración expresa dependencia del Padre y busca su voluntad. Jesús enseñó a pedir protección del mal; la oración no debe convertirse en una fórmula repetitiva para controlar poderes espirituales.", references: "Mateo 6:9-13; Efesios 6:18; Filipenses 4:6-7"),
      StudySection(title: "28. La Palabra de Dios frente a la mentira", content: "Jesús respondió a la tentación citando correctamente las Escrituras. El uso fiel de la Palabra exige comprender el contexto y rechazar la manipulación de versículos para justificar errores.", references: "Mateo 4:4-10; Salmos 119:105; 2 Timoteo 2:15"),
      StudySection(title: "29. La sobriedad y vigilancia del creyente", content: "La vigilancia bíblica no significa vivir obsesionado con el diablo. Significa mantener dominio propio, discernimiento y firmeza en la fe, reconociendo que la oposición existe sin atribuirle todo acontecimiento.", references: "1 Pedro 5:8-9; 1 Tesalonicenses 5:6-8; Marcos 14:38"),
      StudySection(title: "30. Resistir al diablo y acercarse a Dios", content: "Santiago relaciona la resistencia al diablo con someterse primero a Dios, acercarse a Él, limpiar las manos y purificar el corazón. La vida espiritual no se reduce a confrontaciones verbales.", references: "Santiago 4:7-10; 1 Pedro 5:9"),
      StudySection(title: "31. No dar lugar al diablo mediante el pecado", content: "Pablo advierte que la ira no resuelta puede abrir espacio al pecado y al adversario. El contexto destaca el perdón, la verdad y la conducta nueva, no una interpretación supersticiosa de cada conflicto.", references: "Efesios 4:25-32; 2 Corintios 2:10-11"),
      StudySection(title: "32. El perdón y la unidad como protección comunitaria", content: "La falta de perdón y las divisiones pueden ser aprovechadas para dañar la comunión de la Iglesia. La respuesta apostólica es perdonar, restaurar con sabiduría y actuar con amor y verdad.", references: "2 Corintios 2:5-11; Colosenses 3:12-15; Efesios 4:1-3"),
      StudySection(title: "33. El discernimiento de espíritus y la prueba de las enseñanzas", content: "La Iglesia debe probar los espíritus y examinar los mensajes a la luz de la confesión bíblica de Jesucristo. Ninguna profecía, visión o experiencia está por encima de la Palabra de Dios.", references: "1 Juan 4:1-3; 1 Corintios 12:10; 1 Tesalonicenses 5:19-22"),
      StudySection(title: "34. Falsas doctrinas y engaño espiritual", content: "La Escritura advierte sobre doctrinas de demonios y maestros engañosos. El discernimiento requiere conocer el evangelio, examinar el fruto y evitar tanto la credulidad como las acusaciones irresponsables.", references: "1 Timoteo 4:1-5; 2 Pedro 2:1-3; Mateo 24:4-5"),
      StudySection(title: "35. La idolatría y la participación en prácticas ocultistas", content: "La Biblia prohíbe buscar dirección o poder mediante prácticas ocultistas y llama a la fidelidad exclusiva a Dios. La respuesta cristiana es abandonar esas prácticas y acudir al Señor, no experimentar con ellas.", references: "Deuteronomio 18:9-14; Hechos 19:18-20; 1 Corintios 10:20-21"),
      StudySection(title: "36. La autoridad espiritual no es un poder humano autónomo", content: "Los discípulos ejercieron autoridad recibida de Cristo, pero no como propiedad personal ni medio de fama. Toda autoridad ministerial está subordinada al Señor y debe ejercerse con humildad y responsabilidad.", references: "Lucas 10:17-20; Hechos 3:12-16; 2 Corintios 4:5"),
      StudySection(title: "37. El nombre de Jesús no es una fórmula mágica", content: "En Hechos, el nombre de Jesús representa su autoridad e identidad. El relato de los hijos de Esceva advierte contra repetirlo como conjuro sin relación de fe y obediencia al Señor.", references: "Hechos 19:13-17; Hechos 3:6; Colosenses 3:17"),
      StudySection(title: "38. La diferencia entre opresión espiritual y problemas humanos", content: "La Biblia reconoce la realidad de la oposición espiritual, pero no enseña que todo sufrimiento, enfermedad, conflicto o trastorno tenga origen demoníaco. Es necesario actuar con prudencia y buscar ayuda apropiada según cada situación.", references: "Juan 9:1-3; Lucas 13:1-5; 1 Timoteo 5:23; Santiago 5:14-16"),
      StudySection(title: "39. La dignidad y el cuidado de las personas vulnerables", content: "Los relatos de liberación muestran a Jesús restaurando dignidad y atendiendo a personas marginadas. La Iglesia debe proteger a quienes sufren, nunca humillarlos, amenazarlos o exponerlos a prácticas dañinas.", references: "Marcos 5:1-20; Lucas 8:35; Mateo 9:35-36"),
      StudySection(title: "40. La responsabilidad pastoral en asuntos de guerra espiritual", content: "Los líderes deben enseñar con sobriedad, evitar el sensacionalismo y no manipular el miedo. La oración y el acompañamiento deben respetar la dignidad, seguridad y conciencia de cada persona.", references: "1 Pedro 5:1-4; 2 Timoteo 2:24-26; Tito 2:1"),
      StudySection(title: "41. La prohibición de la curiosidad y el sensacionalismo", content: "La Biblia dirige la atención hacia Dios y su voluntad, no hacia detalles secretos del mundo demoníaco. Las especulaciones sobre jerarquías, nombres o rituales no revelados no deben convertirse en doctrina.", references: "Deuteronomio 29:29; Colosenses 2:18-19; 1 Timoteo 1:3-7"),
      StudySection(title: "42. La protección de Dios y la confianza del creyente", content: "La protección divina no significa que el cristiano nunca enfrente pruebas. Significa que Dios permanece fiel, sostiene a los suyos y guarda su propósito incluso en circunstancias difíciles.", references: "Salmos 121:1-8; Juan 17:15; 2 Tesalonicenses 3:3"),
      StudySection(title: "43. El Espíritu Santo fortalece al creyente", content: "El Espíritu Santo guía a la verdad, produce fruto y capacita para vivir en santidad. La resistencia al mal no se consigue mediante autosuficiencia, sino por la obra del Espíritu en quienes pertenecen a Cristo.", references: "Juan 14:16-17, 26; Gálatas 5:16-25; Romanos 8:13-16"),
      StudySection(title: "44. La comunión del Padre, del Hijo y del Espíritu Santo en la victoria cristiana", content: "El Padre libra conforme a su voluntad, el Hijo venció mediante su obra redentora y el Espíritu aplica la vida nueva al creyente. La Escritura presenta una sola obra divina de salvación sin confundir a las personas de la Trinidad.", references: "Efesios 1:3-14; Romanos 8:11-17; 1 Pedro 1:2"),
      StudySection(title: "45. La Iglesia unida en la verdad y el amor", content: "La comunidad cristiana se fortalece mediante enseñanza sana, oración, servicio, perdón y cuidado mutuo. La unidad no se basa en miedo compartido, sino en la verdad del evangelio y el amor de Cristo.", references: "Hechos 2:42-47; Efesios 4:1-16; Colosenses 3:14-16"),
      StudySection(title: "46. La misión de la Iglesia frente a un mundo en oposición", content: "La Iglesia no fue enviada a perseguir personas, sino a anunciar el evangelio, hacer discípulos y servir con compasión. La lucha cristiana no es contra seres humanos, sino una perseverancia en la verdad y la justicia de Dios.", references: "Mateo 28:18-20; Efesios 6:12; 2 Timoteo 2:24-26"),
      StudySection(title: "47. El juicio final sobre Satanás y sus obras", content: "La Biblia anuncia que el diablo será juzgado definitivamente. Su actividad presente es temporal y no puede alterar el desenlace establecido por Dios.", references: "Mateo 25:41; Apocalipsis 20:1-3, 10"),
      StudySection(title: "48. La derrota definitiva del mal en la nueva creación", content: "La esperanza final incluye el fin de la muerte, el dolor y toda oposición contra Dios. La nueva creación será la morada de justicia y comunión, donde el mal no tendrá lugar.", references: "Apocalipsis 21:1-5; 22:1-5; 1 Corintios 15:24-28"),
      StudySection(title: "49. Vivir sin temor supersticioso y con reverencia a Dios", content: "El creyente no debe negar la realidad del mal ni vivir dominado por el miedo. La respuesta bíblica es confiar en Dios, obedecer a Cristo, practicar el bien y permanecer sobrio en la fe.", references: "Romanos 8:31-39; 2 Timoteo 1:7; 1 Juan 4:4"),
      StudySection(title: "50. La victoria de Cristo como fundamento de la esperanza diaria", content: "La victoria cristiana no consiste en prometer una vida sin conflictos, sino en permanecer unidos a Cristo, quien sostiene a su pueblo y asegura la consumación de su reino. Por eso la Iglesia puede perseverar con confianza y humildad.", references: "Juan 16:33; Romanos 16:20; 1 Corintios 15:57-58"),
    ],
    conclusion: "La enseñanza bíblica sobre Satanás y los demonios debe producir discernimiento, no fascinación; vigilancia, no temor supersticioso; y confianza en Dios, no autosuficiencia. Satanás es un adversario real, pero no es eterno, omnipotente ni igual a Dios. Los demonios son seres espirituales malignos, pero están sujetos a la autoridad del Señor. Jesucristo manifestó su autoridad sobre ellos, venció mediante la cruz y la resurrección, y será quien consuma definitivamente la derrota del mal. Por tanto, la Iglesia está llamada a permanecer firme en la verdad, revestirse de la armadura de Dios, orar, cuidar a los vulnerables, rechazar toda práctica ocultista y anunciar el evangelio con amor. El Padre sostiene su propósito, el Hijo reina victorioso y el Espíritu Santo fortalece a los creyentes. La esperanza cristiana no se apoya en conocer supuestos secretos del mundo espiritual, sino en conocer y obedecer al Dios verdadero revelado en las Escrituras."
  ),
Study(
    number: '80',
    title: "El juicio final de Dios: justicia, responsabilidad humana y destino eterno",
    subtitle: "Un estudio bíblico sobre el juicio universal, la justicia divina, la autoridad de Jesucristo y la esperanza de quienes pertenecen a Él.",
    introduction: "La Biblia enseña que Dios juzgará al mundo con justicia y que toda persona dará cuenta de su vida delante de Él. Este estudio no repite el estado intermedio ni la segunda venida, tratados anteriormente, sino que examina el juicio definitivo: su certeza, la santidad de Dios, la responsabilidad humana, la evaluación de las obras, la autoridad judicial del Hijo y el destino final. También explica la relación entre la salvación por gracia y el juicio según las obras: estas no compran la salvación, pero manifiestan la realidad de la fe. El propósito no es alimentar miedo ni especulaciones, sino llamar al arrepentimiento, fortalecer la esperanza de quienes están en Cristo y recordar a la Iglesia su responsabilidad de vivir y anunciar el evangelio. Desde la perspectiva trinitaria, el Padre es el Juez justo, el Hijo ejerce la autoridad judicial que le ha sido confiada y el Espíritu Santo convence al mundo de pecado, justicia y juicio. Estas distinciones personales expresan la unidad del único Dios en su obra santa y justa.",
    sections: [
      StudySection(title: "1. La certeza del juicio", content: "La historia humana culminará en un juicio justo de Dios; esta verdad llama a vivir responsablemente y no a especular sobre fechas.", references: "Hebreos 9:27; Hechos 17:30-31; Romanos 2:5-6"),
      StudySection(title: "2. Dios, Juez de toda la tierra", content: "El juicio pertenece al carácter santo de Dios. El Juez de toda la tierra hará lo recto; su veredicto no es arbitrario.", references: "Génesis 18:25; Salmos 9:7-8; 96:13"),
      StudySection(title: "3. La universalidad del juicio", content: "Todos comparecerán ante Dios. Ninguna posición social, riqueza o influencia coloca a alguien fuera de su autoridad.", references: "Romanos 14:10-12; 2 Corintios 5:10; Apocalipsis 20:12"),
      StudySection(title: "4. La responsabilidad personal", content: "Cada persona dará cuenta de su propia vida. Nadie puede trasladar a otros la responsabilidad de sus decisiones.", references: "Romanos 14:12; Ezequiel 18:20; Gálatas 6:5"),
      StudySection(title: "5. La imparcialidad del Juez", content: "Dios no puede ser sobornado por riquezas, reputación o favoritismos. Su juicio no está condicionado por apariencias.", references: "Romanos 2:2,11; 1 Pedro 1:17; Deuteronomio 10:17"),
      StudySection(title: "6. El conocimiento perfecto de Dios", content: "Nada permanece oculto delante del Señor. Su conocimiento garantiza que el juicio considere la verdad completa de cada vida.", references: "Salmos 139:1-4; Hebreos 4:12-13; Eclesiastés 12:14"),
      StudySection(title: "7. La santidad como norma moral", content: "Dios no define el bien y el mal por conveniencia. Su naturaleza santa expone el pecado y muestra la necesidad de redención.", references: "Levítico 19:2; Isaías 6:3; 1 Pedro 1:15-16"),
      StudySection(title: "8. La justicia frente a la maldad", content: "La justicia final asegura que la violencia y la injusticia no tendrán la última palabra. Dios no ignora el sufrimiento.", references: "Salmos 9:7-10; Eclesiastés 3:16-17; Romanos 12:19"),
      StudySection(title: "9. La paciencia antes del juicio", content: "La demora del juicio no significa aprobación del pecado. La paciencia divina ofrece oportunidad para el arrepentimiento.", references: "Romanos 2:4-5; 2 Pedro 3:9; Romanos 9:22-23"),
      StudySection(title: "10. El llamado al arrepentimiento", content: "Dios llama a abandonar el pecado y volverse a Él. El anuncio del juicio comunica la urgencia del arrepentimiento y la esperanza del evangelio.", references: "Hechos 17:30-31; Hechos 3:19; Lucas 13:3"),
      StudySection(title: "11. La conciencia y la responsabilidad moral", content: "La conciencia da testimonio de deberes morales, aunque puede equivocarse. Dios juzga con conocimiento perfecto.", references: "Romanos 2:14-16; Romanos 1:18-20; 1 Corintios 4:4-5"),
      StudySection(title: "12. La responsabilidad conforme a la luz recibida", content: "La Escritura enseña que existe responsabilidad relacionada con el conocimiento recibido. El juicio de casos particulares pertenece a Dios.", references: "Lucas 12:47-48; Romanos 2:12-16; Juan 15:22"),
      StudySection(title: "13. Las obras serán examinadas", content: "Las obras son evidencia de la vida y de la respuesta a Dios. No compran la salvación, pero manifiestan la realidad de la fe.", references: "Romanos 2:6-8; Mateo 16:27; Apocalipsis 20:12-13"),
      StudySection(title: "14. La gracia y el juicio según las obras", content: "La salvación es regalo recibido por fe, no salario por méritos. El juicio manifiesta la vida sin convertir las obras en causa de justificación.", references: "Efesios 2:8-10; Romanos 3:23-28; 2 Corintios 5:10"),
      StudySection(title: "15. La fe genuina produce fruto", content: "Las obras no sustituyen la fe, pero una fe viva produce obediencia. Santiago combate una profesión vacía sin misericordia.", references: "Santiago 2:14-26; Gálatas 5:6,22-23; Juan 15:5-8"),
      StudySection(title: "16. Las palabras y las intenciones", content: "Jesús enseñó que las palabras revelan aspectos del corazón y que las motivaciones importan delante de Dios.", references: "Mateo 12:36-37; 1 Corintios 4:5; Romanos 2:16"),
      StudySection(title: "17. Los secretos del corazón", content: "Dios puede revelar las intenciones que las personas ocultan. Esta verdad llama a la sinceridad y al abandono de la hipocresía.", references: "Romanos 2:16; 1 Corintios 4:5; Lucas 12:2-3"),
      StudySection(title: "18. Jesucristo, Juez establecido por Dios", content: "El Padre ha confiado el juicio al Hijo. Jesucristo ejerce esta autoridad conforme a la voluntad del Padre.", references: "Juan 5:22-27; Hechos 10:42; Hechos 17:31"),
      StudySection(title: "19. La autoridad judicial y la identidad del Hijo", content: "La autoridad de Jesús para juzgar está vinculada con su identidad y dignidad como Hijo. Los creyentes reconocen su señorío.", references: "Juan 5:23-27; Colosenses 1:15-20; Hebreos 1:8"),
      StudySection(title: "20. El juicio del Hijo en unidad con el Padre", content: "El juicio de Jesucristo no contradice al Padre. Ambos actúan en perfecta unidad divina, sin confusión de personas.", references: "Juan 5:19-23; Juan 8:16; Juan 10:30"),
      StudySection(title: "21. El Espíritu Santo y la convicción de juicio", content: "Jesús enseñó que el Espíritu convencería al mundo de pecado, justicia y juicio. Su obra señala la gravedad del rechazo a Cristo.", references: "Juan 16:7-11; Juan 15:26-27"),
      StudySection(title: "22. La Trinidad en la obra de juzgar", content: "El Padre es Juez, el Hijo recibe autoridad judicial y el Espíritu convence al mundo. Estas distinciones personales no dividen al único Dios.", references: "Romanos 2:16; Juan 5:22-27; Juan 16:8-11"),
      StudySection(title: "23. El tribunal de Cristo", content: "Los creyentes comparecerán ante el tribunal de Cristo. Esto destaca la responsabilidad de vivir para agradar al Señor.", references: "2 Corintios 5:9-10; Romanos 14:10-12"),
      StudySection(title: "24. La evaluación de la obra de los creyentes", content: "La obra edificada sobre Jesucristo será probada. El pasaje llama a servir con fidelidad y calidad.", references: "1 Corintios 3:10-15; Colosenses 3:23-25"),
      StudySection(title: "25. La recompensa y la fidelidad", content: "La Biblia habla de recompensa para quienes sirven fielmente, pero advierte contra buscar reconocimiento humano. La recompensa no compra la gracia.", references: "Mateo 6:1-4; 1 Corintios 3:8; 2 Timoteo 4:7-8"),
      StudySection(title: "26. Ninguna condenación en Cristo", content: "Quienes pertenecen a Cristo reciben justificación y no están bajo condenación. Esta seguridad conduce a vivir por el Espíritu.", references: "Romanos 8:1-4,33-34; Juan 5:24"),
      StudySection(title: "27. La seguridad y la perseverancia", content: "La seguridad cristiana descansa en Cristo y la fidelidad de Dios. Las advertencias llaman a perseverar y no caer en presunción.", references: "Juan 10:27-29; Colosenses 1:21-23; Hebreos 3:12-14"),
      StudySection(title: "28. La disciplina presente y el juicio final", content: "La disciplina divina busca corregir a sus hijos, mientras el juicio final pertenece a la consumación de la justicia. No toda dificultad es castigo.", references: "Hebreos 12:5-11; 1 Corintios 11:31-32; Juan 9:1-3"),
      StudySection(title: "29. El juicio de las naciones", content: "Mateo 25 presenta la separación de las naciones y relaciona la respuesta hacia los necesitados con la relación con el Rey.", references: "Mateo 25:31-46; Santiago 2:14-17"),
      StudySection(title: "30. La separación entre justicia e injusticia", content: "La separación final hará manifiesta la diferencia entre quienes pertenecen al Señor y quienes persisten en rechazarlo. No anticipemos veredictos individuales.", references: "Mateo 13:40-43,47-50; Mateo 25:32-33"),
      StudySection(title: "31. El libro de la vida", content: "Apocalipsis utiliza la imagen del libro de la vida para hablar de quienes pertenecen a Dios. No debemos pretender conocer información no revelada.", references: "Éxodo 32:32-33; Filipenses 4:3; Apocalipsis 20:12,15"),
      StudySection(title: "32. Los libros y el registro de las obras", content: "Apocalipsis presenta libros abiertos y a las personas juzgadas según sus obras. Nada queda olvidado delante de la justicia divina.", references: "Daniel 7:9-10; Apocalipsis 20:11-13; Eclesiastés 12:14"),
      StudySection(title: "33. El gran trono blanco", content: "Apocalipsis 20 describe el gran trono blanco y la comparecencia de los muertos ante Dios. Proclama la solemnidad del juicio universal.", references: "Apocalipsis 20:11-15"),
      StudySection(title: "34. La muerte segunda y el destino final", content: "Apocalipsis utiliza la expresión muerte segunda para describir el destino final asociado con el lago de fuego. Es una advertencia solemne sin sensacionalismo.", references: "Apocalipsis 20:14-15; 21:8"),
      StudySection(title: "35. El juicio de los ángeles rebeldes", content: "La Escritura enseña que los ángeles que pecaron no quedarán fuera de la justicia divina. Ninguna criatura puede rebelarse impunemente.", references: "2 Pedro 2:4; Judas 6; 1 Corintios 6:3"),
      StudySection(title: "36. La justicia frente a las víctimas", content: "El juicio ofrece esperanza a quienes padecieron injusticia, porque Dios conoce su sufrimiento. La Iglesia debe defender al vulnerable.", references: "Salmos 10:14-18; Lucas 18:7-8; Romanos 12:19"),
      StudySection(title: "37. El juicio no autoriza la venganza", content: "La certeza de que Dios juzgará no permite tomar justicia por las propias manos. La respuesta cristiana incluye hacer el bien.", references: "Romanos 12:17-21; 1 Pedro 2:21-23; Miqueas 6:8"),
      StudySection(title: "38. La responsabilidad de quienes enseñan", content: "Quienes enseñan la Palabra tienen responsabilidad especial. El liderazgo exige fidelidad, integridad y cuidado de las personas.", references: "Santiago 3:1; 1 Pedro 5:2-3; 2 Timoteo 4:1-5"),
      StudySection(title: "39. El juicio y la proclamación del evangelio", content: "Anunciar el juicio sin proclamar la gracia presenta un mensaje incompleto. El evangelio llama al arrepentimiento y ofrece perdón en Cristo.", references: "Marcos 1:14-15; Juan 3:16-18; Hechos 17:30-31"),
      StudySection(title: "40. La esperanza cristiana ante el juicio", content: "El creyente espera el día de Dios con confianza reverente, porque su esperanza está en Cristo. Esta expectativa impulsa una vida santa.", references: "2 Pedro 3:11-14; 1 Juan 4:17-18; Tito 2:11-14"),
      StudySection(title: "41. La santidad ante el juicio venidero", content: "La esperanza del juicio conduce a una vida apartada para Dios. La santidad es fruto de la gracia y respuesta al Señor justo.", references: "2 Pedro 3:10-14; 1 Pedro 1:13-17; Hebreos 12:14"),
      StudySection(title: "42. La humildad ante el juicio de Dios", content: "No conocemos perfectamente las motivaciones ni el destino de otras personas. Debemos evitar condenas precipitadas y dejar el veredicto al Juez.", references: "Mateo 7:1-5; Romanos 14:4,10-13; 1 Corintios 4:5"),
      StudySection(title: "43. La misericordia y la verdad", content: "Quien ha recibido misericordia debe actuar con misericordia, sin relativizar la verdad ni justificar injusticias. La fe se expresa en trato compasivo.", references: "Mateo 5:7; Mateo 23:23; Santiago 2:12-13"),
      StudySection(title: "44. La resurrección y la comparecencia", content: "La enseñanza bíblica conecta la resurrección con el juicio: los muertos serán levantados y comparecerán ante Dios. Aquí se estudia su función judicial.", references: "Juan 5:28-29; Hechos 24:15; Apocalipsis 20:12-13"),
      StudySection(title: "45. El juicio y la renovación de todas las cosas", content: "El juicio se relaciona con la eliminación definitiva del mal y la manifestación de justicia en la nueva creación, bajo el gobierno perfecto de Dios.", references: "2 Pedro 3:13; Apocalipsis 21:1-5; Romanos 8:19-23"),
      StudySection(title: "46. El fin de la injusticia y la rebelión", content: "El juicio establece que la rebelión contra Dios no continuará. El mal será juzgado y la creación liberada de aquello que la corrompe.", references: "Apocalipsis 20:10-15; 21:4; 1 Corintios 15:24-26"),
      StudySection(title: "47. La adoración al Juez justo", content: "La respuesta adecuada ante la justicia de Dios es reverencia y adoración. Su carácter perfecto es digno de confianza y alabanza.", references: "Apocalipsis 15:3-4; 19:1-2; Salmos 98:7-9"),
      StudySection(title: "48. Vivir a la luz del juicio venidero", content: "Esta doctrina debe transformar las decisiones presentes: hablar con verdad, actuar con justicia, perdonar, servir y perseverar en la fe.", references: "2 Corintios 5:9-11; Colosenses 3:17; 1 Pedro 4:5-7"),
      StudySection(title: "49. Anunciar a Cristo como Salvador y Juez", content: "La Iglesia anuncia a Jesucristo como Salvador y Juez, llamando a la reconciliación con Dios con claridad, respeto y compasión.", references: "2 Corintios 5:18-20; Hechos 10:42-43; 2 Timoteo 4:1-2"),
      StudySection(title: "50. La consumación de la justicia y la gloria de Dios", content: "La justicia divina quedará plenamente manifestada. El Padre cumple su propósito, el Hijo ejerce el juicio confiado y el Espíritu da testimonio.", references: "Romanos 2:16; Juan 5:22-27; Apocalipsis 21:1-7"),
    ],
    conclusion: "El juicio final es una verdad central de la esperanza y la responsabilidad cristianas. Dios juzgará con conocimiento perfecto, sin parcialidad y conforme a su justicia. Jesucristo ha sido establecido como Juez, y toda persona comparecerá ante Él. Las obras serán examinadas como evidencia de la vida, pero la salvación sigue siendo por gracia mediante la fe, no por mérito humano. Para quienes están en Cristo no hay condenación, y esa seguridad debe producir perseverancia, santidad y servicio. El juicio sostiene también la esperanza de las víctimas de la injusticia, porque el mal no tendrá la última palabra. La Iglesia debe anunciar el evangelio con verdad y misericordia, evitar condenas precipitadas y dejar el veredicto definitivo en manos de Dios. El Padre juzga con justicia, el Hijo ejerce el juicio y el Espíritu Santo da testimonio de la verdad. Vivamos con reverencia, confianza y fidelidad, esperando la consumación de la justicia y la renovación de todas las cosas."
  ),
];
